# ============================================================
# ACESSO AOS DADOS
# ============================================================

get_project <- function(project_id) {
  table_database[[project_id]]
}


get_table <- function(project_id, table_id) {
  project <- get_project(project_id)
  project$tables[[table_id]]
}


get_version <- function(project_id, table_id, version_id) {
  table_object <- get_table(project_id, table_id)
  table_object$versions[[version_id]]
}


# ============================================================
# FORMATAÇÃO E CÓDIGO DE EDIÇÃO
# ============================================================

format_number <- function(
    value,
    digits = 1,
    decimal_mark = ",",
    trim_zero = FALSE
) {
  if (is.null(value) || length(value) == 0 || is.na(value)) {
    return("--")
  }
  
  result <- formatC(
    value,
    format = "f",
    digits = digits,
    decimal.mark = decimal_mark
  )
  
  if (trim_zero) {
    pattern <- paste0("\\", decimal_mark, "0+$")
    result <- sub(pattern, "", result)
  }
  
  result
}


format_p_value <- function(value, decimal_mark = ",") {
  if (is.null(value) || length(value) == 0 || is.na(value)) {
    return("")
  }
  
  format_number(value, digits = 3, decimal_mark = decimal_mark)
}


convert_decimal_mark_in_text <- function(
    value,
    decimal_mark
) {
  if (
    is.null(value) ||
    length(value) == 0
  ) {
    return("")
  }
  
  value <- as.character(value)
  
  if (
    is.null(decimal_mark) ||
    !decimal_mark %in% c(",", ".")
  ) {
    return(value)
  }
  
  source_mark <- if (identical(decimal_mark, ",")) {
    "."
  } else {
    ","
  }
  
  pattern <- paste0(
    "(?<=\\d)",
    if (identical(source_mark, ".")) {
      "\\."
    } else {
      ","
    },
    "(?=\\d)"
  )
  
  gsub(
    pattern = pattern,
    replacement = decimal_mark,
    x = value,
    perl = TRUE
  )
}


format_cell <- function(value, type, decimal_mark) {
  if (identical(type, "text")) {
    return(
      convert_decimal_mark_in_text(
        value,
        decimal_mark
      )
    )
  }
  
  if (type == "integer") {
    return(as.character(value))
  }
  
  if (type == "n_percent") {
    percentage <- format_number(
      value$percent,
      digits = 1,
      decimal_mark = decimal_mark
    )
    
    return(paste0(value$n, " (", percentage, "%)"))
  }
  
  if (type == "mean_sd") {
    mean_value <- format_number(
      value$mean,
      digits = 2,
      decimal_mark = decimal_mark
    )
    
    sd_value <- format_number(
      value$sd,
      digits = 2,
      decimal_mark = decimal_mark
    )
    
    return(paste0(mean_value, " ± ", sd_value))
  }
  
  if (type == "median_range") {
    median_value <- format_number(
      value$median,
      digits = 1,
      decimal_mark = decimal_mark
    )
    
    min_value <- format_number(
      value$min,
      digits = 1,
      decimal_mark = decimal_mark,
      trim_zero = TRUE
    )
    
    max_value <- format_number(
      value$max,
      digits = 1,
      decimal_mark = decimal_mark,
      trim_zero = TRUE
    )
    
    return(
      paste0(
        median_value,
        " [",
        min_value,
        " - ",
        max_value,
        "]"
      )
    )
  }
  
  as.character(value)
}


extract_addable_value <- function(value, type) {
  if (type == "integer") {
    return(as.numeric(value))
  }
  
  if (type == "n_percent") {
    return(as.numeric(value$n))
  }
  
  NA_real_
}


format_total_cell <- function(row, decimal_mark) {
  micro_value <- extract_addable_value(row$micro, row$type)
  control_value <- extract_addable_value(row$control, row$type)
  
  if (is.na(micro_value) || is.na(control_value)) {
    return("—")
  }
  
  format_number(
    micro_value + control_value,
    digits = 0,
    decimal_mark = decimal_mark,
    trim_zero = TRUE
  )
}


is_valid_hex_color <- function(value) {
  if (is.null(value) || length(value) == 0) {
    return(FALSE)
  }
  
  grepl("^#[0-9A-Fa-f]{6}$", value)
}


display_or_placeholder <- function(value, placeholder) {
  if (is.null(value) || !nzchar(trimws(value))) {
    return(placeholder)
  }
  
  value
}


encode_edit_state <- function(state) {
  raw_state <- serialize(state, connection = NULL, version = 3)
  hex_state <- paste(sprintf("%02X", as.integer(raw_state)), collapse = "")
  paste0("ED1-", hex_state)
}


decode_edit_state <- function(code) {
  clean_code <- trimws(code)
  
  if (!startsWith(clean_code, "ED1-")) {
    stop("O código não começa com ED1-.")
  }
  
  hex_state <- substring(clean_code, 5)
  
  if (!nzchar(hex_state) || nchar(hex_state) %% 2 != 0) {
    stop("O tamanho do código é inválido.")
  }
  
  if (grepl("[^0-9A-Fa-f]", hex_state)) {
    stop("O código contém caracteres inválidos.")
  }
  
  positions <- seq(1, nchar(hex_state), by = 2)
  byte_text <- substring(hex_state, positions, positions + 1)
  raw_state <- as.raw(strtoi(byte_text, base = 16L))
  
  unserialize(raw_state)
}


escape_latex <- function(value) {
  value <- gsub("\\\\", "\\\\textbackslash{}", value)
  value <- gsub("([#$%&_{}])", "\\\\\\1", value)
  value <- gsub("\\^", "\\\\textasciicircum{}", value)
  value <- gsub("~", "\\\\textasciitilde{}", value)
  value
}


html_escape <- function(value) {
  value <- gsub("&", "&amp;", value, fixed = TRUE)
  value <- gsub("<", "&lt;", value, fixed = TRUE)
  value <- gsub(">", "&gt;", value, fixed = TRUE)
  value <- gsub('"', "&quot;", value, fixed = TRUE)
  value
}



# ============================================================
# COMPONENTE DE COR
# ============================================================

color_control <- function(input_id, label, value) {
  swatch_id <- paste0(input_id, "_swatch")
  
  palette <- c(
    "#000000", "#FFFFFF", "#1D3557", "#315A7D", "#457B9D",
    "#E9EEF3", "#F2F5F8", "#B8C2CC", "#B42318", "#18794E"
  )
  
  palette_buttons <- lapply(
    palette,
    function(color_value) {
      tags$button(
        type = "button",
        class = "color-palette-button",
        `data-color-target` = input_id,
        `data-color-value` = color_value,
        title = color_value,
        style = paste0("background:", color_value, ";")
      )
    }
  )
  
  div(
    class = "color-control",
    tags$label(`for` = input_id, class = "control-label", label),
    div(
      class = "color-control-row",
      div(
        id = swatch_id,
        class = "color-swatch",
        style = paste0("background:", value, ";")
      ),
      textInput(
        inputId = input_id,
        label = NULL,
        value = value,
        placeholder = "#000000",
        width = "100%"
      )
    ),
    div(class = "color-palette", palette_buttons)
  )
}


