            'graph_axis_title_color',
            'graph_axis_text_color',
            'graph_legend_color',
            'graph_label_color'
          ];

          var dynamicSeriesColor =
            event.target.id.indexOf('series_color_') === 0;

          if (
            ids.indexOf(event.target.id) !== -1 ||
            dynamicSeriesColor
          ) {
            updateColorSwatch(
              event.target.id,
              event.target.value.trim()
            );
          }
