        function inlineComputedStyles(source, clone) {
          var sourceElements = [
            source
          ].concat(
            Array.prototype.slice.call(
              source.querySelectorAll('*')
            )
          );

          var cloneElements = [
            clone
          ].concat(
            Array.prototype.slice.call(
              clone.querySelectorAll('*')
            )
          );

          sourceElements.forEach(function(sourceElement, index) {
            var cloneElement = cloneElements[index];

            if (!cloneElement) {
              return;
            }

            var computed = window.getComputedStyle(sourceElement);
            var styleText = '';

            for (var i = 0; i < computed.length; i += 1) {
              var property = computed[i];

              styleText +=
                property +
                ':' +
                computed.getPropertyValue(property) +
                ';';
            }

            cloneElement.setAttribute('style', styleText);
          });
