# ============================================================
# SERVIDOR
# ============================================================

server <- function(input, output, session) {
  
  structure_state <- reactiveValues(
    hidden_rows = character(0),
    hidden_columns = character(0)
  )
  
  history_stack <- reactiveVal(list())
  redo_stack <- reactiveVal(list())
  last_snapshot <- reactiveVal(NULL)
  restoring_snapshot <- reactiveVal(FALSE)
  edit_code_message <- reactiveVal(NULL)
  
  
  # ==========================================================
  # NAVEGAÇÃO PÚBLICA DOS ARTEFATOS NO GITHUB
  # ==========================================================
  
  table_github_loaded <- reactiveVal(NULL)
  graph_github_loaded <- reactiveVal(NULL)
  table_github_status <- reactiveVal(NULL)
  graph_github_status <- reactiveVal(NULL)
  
  
  github_public_artifact_url <- function(
    project_id,
    artifact_type,
    artifact_id,
    version
  ) {
    owner <- Sys.getenv(
      "GITHUB_OWNER",
      unset = "AlvaroRoberto98"
    )
    
    repo <- Sys.getenv(
      "GITHUB_REPO",
      unset = "stat-artifacts"
    )
    
    branch <- Sys.getenv(
      "GITHUB_BRANCH",
      unset = "main"
    )
    
    folder <- if (identical(artifact_type, "table")) {
      "tables"
    } else {
      "figures"
    }
    
    paste0(
      "https://raw.githubusercontent.com/",
      owner,
      "/",
      repo,
      "/",
      branch,
      "/data/projects/",
      project_id,
      "/",
      folder,
      "/",
      artifact_id,
      "/v",
      sprintf("%03d", as.integer(version)),
      ".json?cache_bust=",
      as.integer(
        as.numeric(Sys.time())
      )
    )
  }
  
  
  github_read_public_artifact <- function(
    project_id,
    artifact_type,
    artifact_id,
    version
  ) {
    temp_file <- tempfile(fileext = ".json")
    
    on.exit(
      unlink(temp_file),
      add = TRUE
    )
    
    artifact_url <- github_public_artifact_url(
      project_id = project_id,
      artifact_type = artifact_type,
      artifact_id = artifact_id,
      version = version
    )
    
    tryCatch(
      {
        utils::download.file(
          url = artifact_url,
          destfile = temp_file,
          mode = "wb",
          quiet = TRUE
        )
      },
      error = function(error) {
        stop(
          paste(
            "Falha ao baixar o artefato do GitHub:",
            conditionMessage(error)
          )
        )
      }
    )
    
    if (
      !file.exists(temp_file) ||
      file.info(temp_file)$size <= 0
    ) {
      stop("O GitHub retornou um artefato vazio.")
    }
    
    body <- paste(
      readLines(
        temp_file,
        warn = FALSE,
        encoding = "UTF-8"
      ),
      collapse = "\n"
    )
    
    jsonlite::fromJSON(
      body,
      simplifyVector = FALSE
    )
  }
  
  
  
  github_projects_dataframe <- reactive({
    index <- github_full_index()
    projects <- index$projects
    
    if (is.null(projects) || length(projects) == 0) {
      return(
        data.frame(
          project_id = character(0),
          project_name = character(0),
          analyst = character(0),
          year = integer(0),
          stringsAsFactors = FALSE
        )
      )
    }
    
    data.frame(
      project_id = vapply(
        projects,
        function(project) as.character(project$project_id),
        character(1)
      ),
      project_name = vapply(
        projects,
        function(project) as.character(project$project_name),
        character(1)
      ),
      analyst = vapply(
        projects,
        function(project) as.character(project$analyst),
        character(1)
      ),
      year = vapply(
        projects,
        function(project) as.integer(project$year),
        integer(1)
      ),
      stringsAsFactors = FALSE
    )
  })
  
  
  update_github_filter_choices <- function(prefix) {
    projects <- github_projects_dataframe()
    
    years <- sort(unique(projects$year))
    analysts <- sort(unique(projects$analyst))
    
    updateSelectInput(
      session,
      paste0(prefix, "_filter_year"),
      choices = c(
        "Todos" = "",
        stats::setNames(
          as.character(years),
          as.character(years)
        )
      )
    )
    
    updateSelectInput(
      session,
      paste0(prefix, "_filter_analyst"),
      choices = c(
        "Todos" = "",
        stats::setNames(
          analysts,
          analysts
        )
      )
    )
  }
  
  
  observe({
    github_full_index()
    
    update_github_filter_choices("table")
    update_github_filter_choices("graph")
  })
  
  
  filtered_github_projects <- function(
    year_value,
    analyst_value
  ) {
    projects <- github_projects_dataframe()
    
    if (nzchar(year_value)) {
      projects <- projects[
        projects$year == as.integer(year_value),
        ,
        drop = FALSE
      ]
    }
    
    if (nzchar(analyst_value)) {
      projects <- projects[
        projects$analyst == analyst_value,
        ,
        drop = FALSE
      ]
    }
    
    projects
  }
  
  
  observe({
    projects <- filtered_github_projects(
      input$table_filter_year,
      input$table_filter_analyst
    )
    
    choices <- c(
      "Nenhum — mostrar exemplo" = ""
    )
    
    if (nrow(projects) > 0) {
      labels <- paste0(
        "[",
        projects$project_id,
        "] ",
        projects$project_name
      )
      
      choices <- c(
        choices,
        stats::setNames(
          projects$project_id,
          labels
        )
      )
    }
    
    updateSelectInput(
      session,
      "table_github_project_id",
      choices = choices
    )
  })
  
  
  observe({
    projects <- filtered_github_projects(
      input$graph_filter_year,
      input$graph_filter_analyst
    )
    
    choices <- c(
      "Nenhum — mostrar exemplo" = ""
    )
    
    if (nrow(projects) > 0) {
      labels <- paste0(
        "[",
        projects$project_id,
        "] ",
        projects$project_name
      )
      
      choices <- c(
        choices,
        stats::setNames(
          projects$project_id,
          labels
        )
      )
    }
    
    updateSelectInput(
      session,
      "graph_github_project_id",
      choices = choices
    )
  })
  
  
  find_index_project <- function(project_id) {
    projects <- github_full_index()$projects
    
    positions <- which(
      vapply(
        projects,
        function(project) {
          identical(
            as.character(project$project_id),
            project_id
          )
        },
        logical(1)
      )
    )
    
    if (length(positions) == 0) {
      return(NULL)
    }
    
    projects[[positions[[1]]]]
  }
  
  
  output$table_github_artifact_selector <- renderUI({
    project_id <- input$table_github_project_id
    
    if (is.null(project_id) || !nzchar(project_id)) {
      return(
        selectInput(
          inputId = "table_github_artifact_id",
          label = "Tabela:",
          choices = character(0)
        )
      )
    }
    
    project <- find_index_project(project_id)
    records <- project$tables
    
    if (is.null(records) || length(records) == 0) {
      return(
        selectInput(
          inputId = "table_github_artifact_id",
          label = "Tabela:",
          choices = character(0)
        )
      )
    }
    
    ids <- vapply(records, function(record) record$id, character(1))
    labels <- vapply(
      records,
      function(record) paste0(record$id, " — ", record$title),
      character(1)
    )
    
    selectInput(
      inputId = "table_github_artifact_id",
      label = "Tabela:",
      choices = stats::setNames(ids, labels)
    )
  })
  
  
  output$graph_github_artifact_selector <- renderUI({
    project_id <- input$graph_github_project_id
    
    if (is.null(project_id) || !nzchar(project_id)) {
      return(
        selectInput(
          inputId = "graph_github_artifact_id",
          label = "Gráfico:",
          choices = character(0)
        )
      )
    }
    
    project <- find_index_project(project_id)
    records <- project$figures
    
    if (is.null(records) || length(records) == 0) {
      return(
        selectInput(
          inputId = "graph_github_artifact_id",
          label = "Gráfico:",
          choices = character(0)
        )
      )
    }
    
    ids <- vapply(records, function(record) record$id, character(1))
    labels <- vapply(
      records,
      function(record) paste0(record$id, " — ", record$title),
      character(1)
    )
    
    selectInput(
      inputId = "graph_github_artifact_id",
      label = "Gráfico:",
      choices = stats::setNames(ids, labels)
    )
  })
  
  
  find_artifact_record <- function(
    project_id,
    artifact_type,
    artifact_id
  ) {
    project <- find_index_project(project_id)
    
    records <- if (identical(artifact_type, "table")) {
      project$tables
    } else {
      project$figures
    }
    
    positions <- which(
      vapply(
        records,
        function(record) identical(record$id, artifact_id),
        logical(1)
      )
    )
    
    if (length(positions) == 0) {
      return(NULL)
    }
    
    records[[positions[[1]]]]
  }
  
  
  output$table_github_version_selector <- renderUI({
    req(
      input$table_github_project_id,
      input$table_github_artifact_id
    )
    
    record <- find_artifact_record(
      input$table_github_project_id,
      "table",
      input$table_github_artifact_id
    )
    
    versions <- as.integer(
      unlist(record$versions, use.names = FALSE)
    )
    
    selectInput(
      inputId = "table_github_version",
      label = "Versão:",
      choices = stats::setNames(
        versions,
        paste0("v", versions)
      ),
      selected = max(versions)
    )
  })
  
  
  output$graph_github_version_selector <- renderUI({
    req(
      input$graph_github_project_id,
      input$graph_github_artifact_id
    )
    
    record <- find_artifact_record(
      input$graph_github_project_id,
      "figure",
      input$graph_github_artifact_id
    )
    
    versions <- as.integer(
      unlist(record$versions, use.names = FALSE)
    )
    
    selectInput(
      inputId = "graph_github_version",
      label = "Versão:",
      choices = stats::setNames(
        versions,
        paste0("v", versions)
      ),
      selected = max(versions)
    )
  })
  
  
  observeEvent(input$load_table_from_github, {
    if (
      is.null(input$table_github_project_id) ||
      !nzchar(input$table_github_project_id)
    ) {
      table_github_loaded(NULL)
      table_github_status(
        list(
          ok = TRUE,
          message = "Modo de demonstração ativo."
        )
      )
      return()
    }
    
    tryCatch(
      {
        artifact <- github_read_public_artifact(
          project_id = input$table_github_project_id,
          artifact_type = "table",
          artifact_id = input$table_github_artifact_id,
          version = input$table_github_version
        )
        
        table_github_loaded(artifact)
        
        table_github_status(
          list(
            ok = TRUE,
            message = paste(
              input$table_github_artifact_id,
              paste0("v", input$table_github_version),
              "foi carregada do GitHub."
            )
          )
        )
      },
      error = function(error) {
        table_github_status(
          list(
            ok = FALSE,
            message = conditionMessage(error)
          )
        )
      }
    )
  })
  
  
  observeEvent(input$load_graph_from_github, {
    if (
      is.null(input$graph_github_project_id) ||
      !nzchar(input$graph_github_project_id)
    ) {
      graph_github_loaded(NULL)
      updateTextInput(
        session,
        "graph_project_code",
        value = ""
      )
      graph_github_status(
        list(
          ok = TRUE,
          message = "Modo de demonstração ativo."
        )
      )
      return()
    }
    
    tryCatch(
      {
        graph_restoring_snapshot(TRUE)
        
        artifact <- github_read_public_artifact(
          project_id = input$graph_github_project_id,
          artifact_type = "figure",
          artifact_id = input$graph_github_artifact_id,
          version = input$graph_github_version
        )
        
        graph_github_loaded(artifact)
        
        content <- unwrap_artifact_content(artifact)
        
        if (!is.null(content$title)) {
          updateTextInput(
            session,
            "graph_title",
            value = as.character(content$title)
          )
        }
        
        if (!is.null(content$subtitle)) {
          updateTextInput(
            session,
            "graph_subtitle",
            value = as.character(content$subtitle)
          )
        }
        
        options <- content$options
        
        if (is.null(options)) {
          options <- content$parameters
        }
        
        if (!is.null(options$alpha)) {
          updateSliderInput(
            session,
            "graph_density_alpha",
            value = as.numeric(options$alpha)
          )
        }
        
        if (!is.null(options$adjust)) {
          updateSliderInput(session, "graph_density_adjust",
                            value = as.numeric(options$adjust))
        }
        
        if (identical(content$type, "faceted_scatter")) {
          if (!is.null(options$point_size))
            updateSliderInput(session, "graph_faceted_point_size",
                              value = as.numeric(options$point_size))
          if (!is.null(options$point_stroke))
            updateSliderInput(session, "graph_faceted_point_stroke",
                              value = as.numeric(options$point_stroke))
          if (!is.null(options$point_fill))
            updateTextInput(session, "graph_faceted_point_fill",
                            value = as.character(options$point_fill))
          if (!is.null(options$point_color))
            updateTextInput(session, "graph_faceted_point_color",
                            value = as.character(options$point_color))
          if (!is.null(content$facets$scales))
            updateSelectInput(session, "graph_facet_scales",
                              selected = as.character(content$facets$scales))
          if (!is.null(content$facets$ncol))
            updateNumericInput(session, "graph_facet_columns",
                               value = as.integer(content$facets$ncol))
          
          horizontal_lines <- options$horizontal_lines
          if (!is.null(horizontal_lines) && length(horizontal_lines) > 0) {
            line <- horizontal_lines[[1]]
            updateCheckboxInput(session, "graph_faceted_show_hline", value = TRUE)
            updateNumericInput(session, "graph_faceted_hline_y",
                               value = as.numeric(line$y))
            updateTextInput(session, "graph_faceted_hline_color",
                            value = if (is.null(line$color)) "black" else as.character(line$color))
            updateSliderInput(session, "graph_faceted_hline_width",
                              value = if (is.null(line$width)) 0.8 else as.numeric(line$width))
          } else {
            updateCheckboxInput(session, "graph_faceted_show_hline", value = FALSE)
          }
        }
        
        if (!is.null(options$width)) {
          updateSliderInput(
            session,
            "graph_boxplot_width",
            value = as.numeric(options$width)
          )
        }
        
        if (!is.null(options$alpha)) {
          updateSliderInput(
            session,
            "graph_boxplot_alpha",
            value = as.numeric(options$alpha)
          )
        }
        
        if (!is.null(options$outlier_size)) {
          updateSliderInput(
            session,
            "graph_boxplot_outlier_size",
            value = as.numeric(options$outlier_size)
          )
        }
        
        if (!is.null(options$outlier_shape)) {
          updateNumericInput(
            session,
            "graph_boxplot_outlier_shape",
            value = as.numeric(options$outlier_shape)
          )
        }
        
        if (!is.null(options$outlier_color)) {
          updateTextInput(
            session,
            "graph_boxplot_outlier_color",
            value = as.character(options$outlier_color)
          )
        }
        
        if (!is.null(options$show_legend)) {
          updateCheckboxInput(
            session,
            "graph_boxplot_show_legend",
            value = isTRUE(options$show_legend)
          )
        }
        
        if (
          identical(content$type, "stacked_bar_percent") &&
          !is.null(options$width)
        ) {
          updateSliderInput(
            session,
            "graph_stacked_bar_width",
            value = as.numeric(options$width)
          )
        }
        
        axes <- content$axes
        
        if (!is.null(axes$x$title)) {
          updateTextInput(
            session,
            "graph_x_label",
            value = as.character(axes$x$title)
          )
        }
        
        if (!is.null(axes$y$title)) {
          updateTextInput(
            session,
            "graph_y_label",
            value = as.character(axes$y$title)
          )
        }
        
        if (!is.null(content$legend$title)) {
          updateTextInput(
            session,
            "graph_legend_title",
            value = as.character(content$legend$title)
          )
        }
        
        updateTextInput(
          session,
          "graph_project_code",
          value = paste(
            input$graph_github_project_id,
            input$graph_github_artifact_id
          )
        )
        
        graph_github_status(
          list(
            ok = TRUE,
            message = paste(
              input$graph_github_artifact_id,
              paste0("v", input$graph_github_version),
              "foi carregado do GitHub."
            )
          )
        )
        
        session$onFlushed(
          function() {
            session$onFlushed(
              function() {
                snapshot <- tryCatch(
                  isolate(graph_snapshot()),
                  error = function(error) NULL
                )
                
                if (!is.null(snapshot)) {
                  reset_graph_history(snapshot)
                }
                
                graph_restoring_snapshot(FALSE)
              },
              once = TRUE
            )
          },
          once = TRUE
        )
      },
      error = function(error) {
        graph_restoring_snapshot(FALSE)
        
        graph_github_status(
          list(
            ok = FALSE,
            message = conditionMessage(error)
          )
        )
      }
    )
  })
  
  observeEvent(
    input$table_github_project_id,
    {
      if (
        is.null(input$table_github_project_id) ||
        !nzchar(input$table_github_project_id)
      ) {
        table_github_loaded(NULL)
        
        table_github_status(
          list(
            ok = TRUE,
            message = "Modo de demonstração ativo."
          )
        )
        
        session$onFlushed(
          function() {
            load_selected_version()
          },
          once = TRUE
        )
      }
    },
    ignoreInit = TRUE
  )
  
  
  observeEvent(
    input$graph_github_project_id,
    {
      if (
        is.null(input$graph_github_project_id) ||
        !nzchar(input$graph_github_project_id)
      ) {
        graph_github_loaded(NULL)
        
        updateTextInput(
          session,
          "graph_project_code",
          value = ""
        )
        
        graph_github_status(
          list(
            ok = TRUE,
            message = "Modo de demonstração ativo."
          )
        )
        
        session$onFlushed(
          function() {
            snapshot <- tryCatch(
              isolate(graph_snapshot()),
              error = function(error) NULL
            )
            
            if (!is.null(snapshot)) {
              reset_graph_history(snapshot)
            }
          },
          once = TRUE
        )
      }
    },
    ignoreInit = TRUE
  )
  
  
  
  render_github_status <- function(status) {
    if (is.null(status)) {
      return(NULL)
    }
    
    tags$small(
      style = paste0(
        "font-weight:600;color:",
        if (isTRUE(status$ok)) "#18794e" else "#b42318",
        ";"
      ),
      paste(
        if (isTRUE(status$ok)) "✓" else "✗",
        status$message
      )
    )
  }
  
  
  output$table_github_load_status <- renderUI({
    render_github_status(
      table_github_status()
    )
  })
  
  
  output$graph_github_load_status <- renderUI({
    render_github_status(
      graph_github_status()
    )
  })
  
  
  output$table_selector <- renderUI({
    req(input$project_id)
    
    project <- get_project(input$project_id)
    
    selectInput(
      inputId = "table_id",
      label = "Tabela:",
      choices = names(project$tables)
    )
  })
  
  
  output$version_selector <- renderUI({
    req(input$project_id, input$table_id)
    
    table_object <- get_table(
      project_id = input$project_id,
      table_id = input$table_id
    )
    
    versions <- names(table_object$versions)
    latest_version <- as.character(max(as.integer(versions)))
    
    selectInput(
      inputId = "table_version",
      label = "Versão:",
      choices = versions,
      selected = latest_version
    )
  })
  
  
  unwrap_artifact_content <- function(artifact) {
    if (!is.null(artifact) && !is.null(artifact$content)) {
      return(artifact$content)
    }
    
    artifact
  }
  
  
  github_table_to_internal <- function(artifact) {
    content <- unwrap_artifact_content(artifact)
    
    if (
      is.null(content$columns) ||
      length(content$columns) == 0 ||
      is.null(content$rows)
    ) {
      stop("A tabela não possui columns e rows válidos.")
    }
    
    column_ids <- vapply(
      content$columns,
      function(column) as.character(column$id),
      character(1)
    )
    
    column_names <- vapply(
      content$columns,
      function(column) as.character(column$name),
      character(1)
    )
    
    internal_keys <- c(
      "parameter",
      "micro",
      "control",
      "p_value"
    )
    
    mapped_ids <- rep(NA_character_, 4)
    mapped_names <- c(
      "Variável",
      "Grupo 1",
      "Grupo 2",
      "p-valor"
    )
    
    number_to_map <- min(length(column_ids), 4)
    
    mapped_ids[seq_len(number_to_map)] <-
      column_ids[seq_len(number_to_map)]
    
    mapped_names[seq_len(number_to_map)] <-
      column_names[seq_len(number_to_map)]
    
    footnote_symbol_map <- character(0)
    
    if (
      !is.null(content$footnotes) &&
      length(content$footnotes) > 0
    ) {
      footnote_symbol_map <- stats::setNames(
        vapply(
          content$footnotes,
          function(note) {
            if (is.null(note$symbol)) {
              as.character(note$id)
            } else {
              as.character(note$symbol)
            }
          },
          character(1)
        ),
        vapply(
          content$footnotes,
          function(note) as.character(note$id),
          character(1)
        )
      )
    }
    
    get_cell <- function(row, column_id) {
      if (
        is.na(column_id) ||
        is.null(row$cells[[column_id]])
      ) {
        return("")
      }
      
      cell <- row$cells[[column_id]]
      value <- cell$value
      
      if (is.null(value)) {
        value <- ""
      }
      
      value <- as.character(value)
      
      if (
        !is.null(cell$footnote_ids) &&
        length(cell$footnote_ids) > 0
      ) {
        note_ids <- as.character(
          unlist(
            cell$footnote_ids,
            use.names = FALSE
          )
        )
        
        note_symbols <- vapply(
          note_ids,
          function(note_id) {
            if (note_id %in% names(footnote_symbol_map)) {
              return(
                unname(
                  footnote_symbol_map[[note_id]]
                )
              )
            }
            
            note_id
          },
          character(1)
        )
        
        value <- paste0(
          value,
          " [",
          paste(
            note_symbols,
            collapse = ", "
          ),
          "]"
        )
      }
      
      value
    }
    
    rows <- lapply(
      content$rows,
      function(row) {
        level <- if (is.null(row$level)) {
          0L
        } else {
          as.integer(row$level)
        }
        
        first_value <- get_cell(
          row,
          mapped_ids[[1]]
        )
        
        if (level > 0) {
          first_value <- paste0(
            strrep("   ", level),
            first_value
          )
        }
        
        list(
          row_id = as.character(row$id),
          type = "text",
          parameter = first_value,
          micro = get_cell(row, mapped_ids[[2]]),
          control = get_cell(row, mapped_ids[[3]]),
          p_value = get_cell(row, mapped_ids[[4]])
        )
      }
    )
    
    footnote <- ""
    
    if (
      !is.null(content$footnotes) &&
      length(content$footnotes) > 0
    ) {
      footnote <- paste(
        vapply(
          content$footnotes,
          function(note) {
            symbol <- if (is.null(note$symbol)) {
              note$id
            } else {
              note$symbol
            }
            
            paste0(
              symbol,
              " ",
              note$text
            )
          },
          character(1)
        ),
        collapse = " "
      )
    }
    
    list(
      caption = if (is.null(content$title)) {
        "Tabela carregada do GitHub"
      } else {
        as.character(content$title)
      },
      columns = stats::setNames(
        mapped_names,
        internal_keys
      ),
      rows = rows,
      footnote = footnote
    )
  }
  
  
