  tracked_snapshot <- debounce(current_snapshot, 500)
  
  
  observeEvent(tracked_snapshot(), {
    if (restoring_snapshot()) {
      return()
    }
    
    new_snapshot <- tracked_snapshot()
    old_snapshot <- last_snapshot()
    
    if (is.null(old_snapshot)) {
      last_snapshot(new_snapshot)
      return()
    }
    
    if (!identical(new_snapshot, old_snapshot)) {
      history <- history_stack()
      history[[length(history) + 1]] <- old_snapshot
      
      history_stack(history)
      redo_stack(list())
      last_snapshot(new_snapshot)
    }
  }, ignoreInit = TRUE)
  
  
  observeEvent(input$undo_change, {
    history <- history_stack()
    
    if (length(history) == 0) {
      showNotification(
        "Não há alterações anteriores para desfazer.",
        type = "message"
      )
      return()
    }
    
    current <- isolate(current_snapshot())
    target <- history[[length(history)]]
    history <- history[-length(history)]
    
    redo <- redo_stack()
    redo[[length(redo) + 1]] <- current
    
    history_stack(history)
    redo_stack(redo)
    apply_snapshot(target)
  })
  
  
