  build_data_cell <- function(row, column_key) {
    if (column_key == "parameter") {
      return(row$parameter)
    }
    
    if (column_key == "micro") {
      return(
        format_cell(
          row$micro,
          row$type,
          input$decimal_mark
        )
      )
    }
    
    if (column_key == "control") {
      return(
        format_cell(
          row$control,
          row$type,
          input$decimal_mark
        )
      )
    }
    
    if (column_key == "p_value") {
      if (identical(row$type, "text")) {
        return(
          convert_decimal_mark_in_text(
            row$p_value,
            input$decimal_mark
          )
        )
      }
      
      return(
        format_p_value(
          row$p_value,
          input$decimal_mark
        )
      )
    }
    
    if (column_key == "total") {
      return(
        format_total_cell(
          row,
          input$decimal_mark
        )
      )
    }
    
    ""
  }
  
  
  build_total_row_cell <- function(rows, column_key) {
    if (column_key == "parameter") {
      return(
        display_or_placeholder(
          input$total_row_label,
          "[Total]"
        )
      )
    }
    
    if (column_key == "p_value") {
      return("")
    }
    
    if (column_key == "micro") {
      values <- vapply(
        rows,
        function(row) extract_addable_value(row$micro, row$type),
        numeric(1)
      )
    } else if (column_key == "control") {
      values <- vapply(
        rows,
        function(row) extract_addable_value(row$control, row$type),
        numeric(1)
      )
    } else if (column_key == "total") {
      values <- vapply(
        rows,
        function(row) {
          micro <- extract_addable_value(row$micro, row$type)
          control <- extract_addable_value(row$control, row$type)
          
          if (is.na(micro) || is.na(control)) {
            return(NA_real_)
          }
          
          micro + control
        },
        numeric(1)
      )
    } else {
      return("")
    }
    
    valid_values <- values[!is.na(values)]
    
    if (length(valid_values) == 0) {
      return("—")
    }
    
    format_number(
      sum(valid_values),
      digits = 0,
      decimal_mark = input$decimal_mark,
      trim_zero = TRUE
    )
  }
  
  
