  flextable_data <- reactive({
    rows <- visible_rows()
    columns <- visible_columns()
    labels <- column_labels()
    
    validate(
      need(
        length(rows) > 0,
        "Todas as linhas estão ocultas. Use Desfazer ou desmarque uma linha."
      ),
      need(
        length(columns) > 0,
        "Todas as colunas estão ocultas."
      )
    )
    
    data_rows <- lapply(
      rows,
      function(row) {
        values <- vapply(
          columns,
          function(column_key) {
            as.character(build_data_cell(row, column_key))
          },
          character(1)
        )
        
        as.list(values)
      }
    )
    
    data <- as.data.frame(
      do.call(rbind, lapply(data_rows, unlist)),
      stringsAsFactors = FALSE,
      check.names = FALSE
    )
    
    names(data) <- columns
    
    if (isTRUE(input$show_total_row)) {
      total_values <- vapply(
        columns,
        function(column_key) {
          as.character(build_total_row_cell(rows, column_key))
        },
        character(1)
      )
      
      total_data <- as.data.frame(
        as.list(total_values),
        stringsAsFactors = FALSE,
        check.names = FALSE
      )
      
      names(total_data) <- columns
      data <- rbind(data, total_data)
    }
    
    list(
      data = data,
      columns = columns,
      labels = labels
    )
  })
  
  
  flextable_object <- reactive({
    table_data <- flextable_data()
    data <- table_data$data
    columns <- table_data$columns
    labels <- table_data$labels
    
    req(
      input$ft_theme,
      input$ft_font_family,
      input$ft_alignment,
      input$ft_padding,
      input$ft_border_width,
      input$ft_border_color,
      input$ft_zebra_color,
      input$ft_body_background
    )
    
    validate(
      need(
        colors_are_valid(),
        "Corrija as cores principais."
      ),
      need(
        is_valid_hex_color(input$ft_border_color),
        "A cor da borda deve usar o formato #RRGGBB."
      ),
      need(
        is_valid_hex_color(input$ft_zebra_color),
        "A cor das linhas alternadas deve usar o formato #RRGGBB."
      ),
      need(
        is_valid_hex_color(input$ft_body_background),
        "A cor de fundo das células deve usar o formato #RRGGBB."
      )
    )
    
    ft <- flextable::flextable(data)
    
    ft <- flextable::set_header_labels(
      ft,
      values = stats::setNames(
        unname(labels[columns]),
        columns
      )
    )
    
    if (input$ft_theme == "vanilla") {
      ft <- flextable::theme_vanilla(ft)
    } else if (input$ft_theme == "booktabs") {
      ft <- flextable::theme_booktabs(ft)
    } else if (input$ft_theme == "box") {
      ft <- flextable::theme_box(ft)
    } else if (input$ft_theme == "zebra") {
      ft <- flextable::theme_zebra(ft)
    } else {
      ft <- flextable::border_remove(ft)
    }
    
    caption_text <- display_or_placeholder(
      input$caption,
      "[Legenda da tabela não informada]"
    )
    
    footnote_text <- display_or_placeholder(
      input$footnote,
      "[Nota de rodapé não informada]"
    )
    
    ft <- flextable::add_header_row(
      ft,
      values = caption_text,
      colwidths = length(columns),
      top = TRUE
    )
    
    ft <- flextable::add_footer_lines(
      ft,
      values = footnote_text
    )
    
    ft <- flextable::font(
      ft,
      fontname = input$ft_font_family,
      part = "all"
    )
    
    ft <- flextable::fontsize(
      ft,
      size = input$font_size,
      part = "body"
    )
    
    ft <- flextable::fontsize(
      ft,
      size = input$font_size,
      part = "header"
    )
    
    ft <- flextable::fontsize(
      ft,
      size = max(8, input$font_size - 2),
      part = "footer"
    )
    
    ft <- flextable::fontsize(
      ft,
      i = 1,
      size = input$font_size + 2,
      part = "header"
    )
    
    ft <- flextable::bold(
      ft,
      i = 1,
      bold = TRUE,
      part = "header"
    )
    
    ft <- flextable::bold(
      ft,
      i = 2,
      bold = TRUE,
      part = "header"
    )
    
    ft <- flextable::italic(
      ft,
      italic = TRUE,
      part = "footer"
    )
    
    ft <- flextable::bg(
      ft,
      i = 1,
      bg = "#FFFFFF",
      part = "header"
    )
    
    ft <- flextable::color(
      ft,
      i = 1,
      color = input$body_text,
      part = "header"
    )
    
    ft <- flextable::bg(
      ft,
      i = 2,
      bg = input$header_background,
      part = "header"
    )
    
    ft <- flextable::color(
      ft,
      i = 2,
      color = input$header_text,
      part = "header"
    )
    
    ft <- flextable::color(
      ft,
      color = input$body_text,
      part = "body"
    )
    
    if (isTRUE(input$ft_use_body_background)) {
      ft <- flextable::bg(
        ft,
        bg = input$ft_body_background,
        part = "body"
      )
    }
    
    ft <- flextable::color(
      ft,
      color = input$body_text,
      part = "footer"
    )
    
    ft <- flextable::padding(
      ft,
      padding = input$ft_padding,
      part = "all"
    )
    
    if (input$ft_alignment == "mixed") {
      ft <- flextable::align(
        ft,
        align = "center",
        part = "all"
      )
      
      if ("parameter" %in% columns) {
        ft <- flextable::align(
          ft,
          j = "parameter",
          align = "left",
          part = "body"
        )
      }
    } else {
      ft <- flextable::align(
        ft,
        align = input$ft_alignment,
        part = "all"
      )
    }
    
    if (
      isTRUE(input$ft_bold_first_column) &&
      "parameter" %in% columns
    ) {
      ft <- flextable::bold(
        ft,
        j = "parameter",
        bold = TRUE,
        part = "body"
      )
    }
    
    if (isTRUE(input$show_total_row) && nrow(data) > 0) {
      ft <- flextable::bold(
        ft,
        i = nrow(data),
        bold = TRUE,
        part = "body"
      )
      
      ft <- flextable::bg(
        ft,
        i = nrow(data),
        bg = input$ft_zebra_color,
        part = "body"
      )
    }
    
    if (
      isTRUE(input$ft_zebra_rows) &&
      nrow(data) >= 2
    ) {
      zebra_rows <- seq(2, nrow(data), by = 2)
      
      ft <- flextable::bg(
        ft,
        i = zebra_rows,
        bg = input$ft_zebra_color,
        part = "body"
      )
    }
    
    border <- officer::fp_border(
      color = input$ft_border_color,
      width = input$ft_border_width
    )
    
    if (input$ft_theme == "minimal") {
      ft <- flextable::border_remove(ft)
    }
    
    if (isTRUE(input$ft_outer_border)) {
      ft <- flextable::border_outer(
        ft,
        border = border,
        part = "all"
      )
    }
    
    if (isTRUE(input$ft_horizontal_lines)) {
      ft <- flextable::border_inner_h(
        ft,
        border = border,
        part = "all"
      )
    }
    
    if (isTRUE(input$ft_vertical_lines)) {
      ft <- flextable::border_inner_v(
        ft,
        border = border,
        part = "all"
      )
    }
    
    ft <- flextable::set_table_properties(
      ft,
      layout = "autofit",
      align = "center"
    )
    
    ft <- flextable::autofit(ft)
    ft
  })
  
  
