    list(
      schema = "LAYOUT-1",
      
      format = list(
        decimal_mark = input$decimal_mark,
        header_background = input$header_background,
        header_text = input$header_text,
        body_text = input$body_text,
        font_size = input$font_size,
        ft_theme = input$ft_theme,
        ft_font_family = input$ft_font_family,
        ft_alignment = input$ft_alignment,
        ft_padding = input$ft_padding,
        ft_border_width = input$ft_border_width,
        ft_border_color = input$ft_border_color,
        ft_outer_border = isTRUE(input$ft_outer_border),
        ft_horizontal_lines = isTRUE(input$ft_horizontal_lines),
        ft_vertical_lines = isTRUE(input$ft_vertical_lines),
        ft_zebra_rows = isTRUE(input$ft_zebra_rows),
        ft_zebra_color = input$ft_zebra_color,
        ft_use_body_background = isTRUE(input$ft_use_body_background),
        ft_body_background = input$ft_body_background,
        ft_bold_first_column = isTRUE(input$ft_bold_first_column)
      )
    )
  })
  
  
  encode_layout_state <- function(layout) {
    code <- encode_edit_state(layout)
    sub("^ED1-", "LAY1-", code)
  }
  
  
  decode_layout_state <- function(code) {
    clean_code <- trimws(code)
    
    if (!startsWith(clean_code, "LAY1-")) {
      stop("O código não começa com LAY1-.")
    }
    
    layout <- decode_edit_state(
      sub("^LAY1-", "ED1-", clean_code)
    )
    
    if (!identical(layout$schema, "LAYOUT-1")) {
      stop("Versão do layout não reconhecida.")
    }
    
    layout
  }
  
  
