        layout_message(
          paste0(
            'Layout "',
            loaded$name,
            '" carregado.'
          )
        )
      },
      
      error = function(error) {
        layout_message(
          paste(
            "Não foi possível carregar o layout salvo:",
            error$message
          )
        )
      }
    )
  })
  
  
