  observeEvent(input$apply_selected_code, {
    code <- trimws(input$edit_code)
    
    if (startsWith(code, "LAY1-")) {
      tryCatch(
        {
          layout <- decode_layout_state(code)
          apply_layout_state(layout)
          layout_message("Layout aplicado com sucesso.")
        },
        
        error = function(error) {
          layout_message(
            paste(
              "Não foi possível aplicar o layout:",
              error$message
            )
          )
        }
      )
      
      return()
    }
    
    tryCatch(
      {
        snapshot <- decode_edit_state(code)
        
        if (!identical(snapshot$schema, "EDIT-1")) {
          stop("Versão do código não reconhecida.")
        }
        
        same_source <- identical(
          snapshot$source,
          isolate(current_snapshot())$source
        )
        
        if (!same_source) {
          stop(
            paste(
              "Este protótipo só aplica códigos da tabela",
              "e versão atualmente abertas."
            )
          )
        }
        
        history <- history_stack()
        history[[length(history) + 1]] <- isolate(current_snapshot())
        
        history_stack(history)
        redo_stack(list())
        apply_snapshot(snapshot)
        
        edit_code_message("Código completo aplicado com sucesso.")
      },
      
      error = function(error) {
        edit_code_message(
          paste(
            "Não foi possível aplicar o código:",
            error$message
          )
        )
      }
    )
  })
  
  
