  build_html_export <- reactive({
    table_data <- flextable_data()
    data <- table_data$data
    columns <- table_data$columns
    labels <- table_data$labels
    
    caption_text <- display_or_placeholder(
      input$caption,
      "[Legenda da tabela não informada]"
    )
    
    footnote_text <- display_or_placeholder(
      input$footnote,
      "[Nota de rodapé não informada]"
    )
    
    header_cells <- paste0(
      "<th style=\"padding:",
      input$ft_padding,
      "px;border:",
      input$ft_border_width,
      "px solid ",
      input$ft_border_color,
      ";background:",
      input$header_background,
      ";color:",
      input$header_text,
      ";font-family:",
      input$ft_font_family,
      ";font-size:",
      input$font_size,
      "px;\">",
      html_escape(unname(labels[columns])),
      "</th>",
      collapse = ""
    )
    
    body_rows <- vapply(
      seq_len(nrow(data)),
      function(row_index) {
        background <- if (
          isTRUE(input$ft_zebra_rows) &&
          row_index %% 2 == 0
        ) {
          input$ft_zebra_color
        } else if (isTRUE(input$ft_use_body_background)) {
          input$ft_body_background
        } else {
          "#FFFFFF"
        }
        
        cells <- vapply(
          columns,
          function(column_key) {
            align <- if (
              input$ft_alignment == "mixed" &&
              column_key == "parameter"
            ) {
              "left"
            } else if (input$ft_alignment == "mixed") {
              "center"
            } else {
              input$ft_alignment
            }
            
            weight <- if (
              isTRUE(input$ft_bold_first_column) &&
              column_key == "parameter"
            ) {
              "700"
            } else {
              "400"
            }
            
            paste0(
              "<td style=\"padding:",
              input$ft_padding,
              "px;border:",
              input$ft_border_width,
              "px solid ",
              input$ft_border_color,
              ";background:",
              background,
              ";color:",
              input$body_text,
              ";text-align:",
              align,
              ";font-family:",
              input$ft_font_family,
              ";font-size:",
              input$font_size,
              "px;font-weight:",
              weight,
              ";\">",
              html_escape(as.character(data[row_index, column_key])),
              "</td>"
            )
          },
          character(1)
        )
        
        paste0("<tr>", paste0(cells, collapse = ""), "</tr>")
      },
      character(1)
    )
    
    paste0(
      "<div style=\"font-family:",
      input$ft_font_family,
      ";color:",
      input$body_text,
      ";\">",
      "<div style=\"font-weight:700;text-align:center;font-size:",
      input$font_size + 2,
      "px;margin-bottom:12px;\">",
      html_escape(caption_text),
      "</div>",
      "<table style=\"border-collapse:collapse;width:100%;\">",
      "<thead><tr>",
      header_cells,
      "</tr></thead>",
      "<tbody>",
      paste0(body_rows, collapse = ""),
      "</tbody>",
      "</table>",
      "<div style=\"font-style:italic;font-size:",
      max(8, input$font_size - 2),
      "px;margin-top:10px;\">",
      html_escape(footnote_text),
      "</div>",
      "</div>"
    )
  })
  
  
  build_latex_export <- reactive({
    table_data <- flextable_data()
    data <- table_data$data
    columns <- table_data$columns
    labels <- table_data$labels
    
    caption_text <- display_or_placeholder(
      input$caption,
      "[Legenda da tabela não informada]"
    )
    
    footnote_text <- display_or_placeholder(
      input$footnote,
      "[Nota de rodapé não informada]"
    )
    
    column_spec <- paste0(
      ifelse(
        columns == "parameter",
        "l",
        "c"
      ),
      collapse = ""
    )
    
    header <- paste(
      escape_latex(unname(labels[columns])),
      collapse = " & "
    )
    
    body <- vapply(
      seq_len(nrow(data)),
      function(row_index) {
        paste0(
          paste(
            escape_latex(
              as.character(
                unlist(
                  data[row_index, columns, drop = TRUE]
                )
              )
            ),
            collapse = " & "
          ),
          " \\\\"
        )
      },
      character(1)
    )
    
    paste0(
      "\\begin{table}[htbp]\n",
      "\\centering\n",
      "\\caption{",
      escape_latex(caption_text),
      "}\n",
      "\\begin{tabular}{",
      column_spec,
      "}\n",
      "\\toprule\n",
      header,
      " \\\\\n",
      "\\midrule\n",
      paste(body, collapse = "\n"),
      "\n\\bottomrule\n",
      "\\end{tabular}\n",
      "\\\\[4pt]\n",
      "\\footnotesize{",
      escape_latex(footnote_text),
      "}\n",
      "\\end{table}"
    )
  })
  
  
  observeEvent(input$generate_export_code, {
    code <- if (input$code_export_type == "html") {
      build_html_export()
    } else {
      build_latex_export()
    }
    
    updateTextAreaInput(
      session,
      "export_code",
      value = code
    )
    
    export_code_message(
      paste(
        "Código",
        toupper(input$code_export_type),
        "gerado."
      )
    )
  })
  
  
  observeEvent(input$copy_export_code, {
