    )
    
    export_code_message(
      "Código copiado para a área de transferência."
    )
  })
  
  
  observeEvent(input$download_export_code, {
    req(input$export_code)
    
    is_html <- input$code_export_type == "html"
    
    filename <- paste0(
      input$table_id,
      "-v",
      input$table_version,
      if (is_html) ".html" else ".tex"
    )
    
    mime <- if (is_html) {
      "text/html"
    } else {
      "text/plain"
    }
    
    session$sendCustomMessage(
      "download-export-code",
      list(
        code = input$export_code,
        filename = filename,
        mime = mime
      )
    )
    
    export_code_message(
      paste("Arquivo", filename, "preparado.")
    )
  })
  
  
