    if (
      is.null(graph_type) ||
      length(graph_type) == 0
    ) {
      return(NULL)
    }
    
    graph_type <- as.character(graph_type[[1]])
    
    if (identical(graph_type, "scatter_plot")) {
      if (
        !is.null(mapping) &&
        !is.null(mapping$facet)
      ) {
        return("faceted_scatter")
      }
      
      return("scatter")
    }
    
    graph_type
  }
  
  
  github_graph_type <- reactive({
