  graph_examples <- reactive({
    examples <- demo_graph_examples()
    content <- github_graph_content()
    
    if (is.null(content)) {
      return(examples)
    }
    
    graph_type <- github_graph_type()
    mapping <- content$mapping
    rows <- content$data
    
    if (is.null(rows) || length(rows) == 0) {
      return(examples)
    }
    
    series_records <- content$series
    series_names <- character(0)
    
    if (
      !is.null(series_records) &&
      length(series_records) > 0
    ) {
      series_names <- stats::setNames(
        vapply(
          series_records,
          function(series) {
            if (is.null(series$source_name)) {
              as.character(series$name)
            } else {
              as.character(series$source_name)
            }
          },
          character(1)
        ),
        vapply(
          series_records,
          function(series) as.character(series$id),
          character(1)
        )
      )
    }
    
    get_value <- function(row, key, default = NA) {
      if (
        is.null(key) ||
        !nzchar(key) ||
        is.null(row[[key]])
      ) {
        return(default)
      }
      
      row[[key]]
    }
    
    get_series_name <- function(row) {
      series_id <- row$series_id
      
      if (
        is.null(series_id) &&
        !is.null(mapping$series)
      ) {
        series_id <- row[[mapping$series]]
      }
      
      if (
        is.null(series_id) &&
        !is.null(mapping$group)
      ) {
        series_id <- row[[mapping$group]]
      }
      
      if (is.null(series_id)) {
        return("Série")
      }
      
      series_id <- as.character(series_id)
      
      if (series_id %in% names(series_names)) {
        return(unname(series_names[[series_id]]))
      }
      
      series_id
    }
    
    if (identical(graph_type, "faceted_scatter")) {
      examples$faceted_scatter <- data.frame(
        x = vapply(
          rows,
          function(row) {
            upload_scalar_numeric(
              get_value(
                row,
                mapping$x,
                NA_real_
              ),
              NA_real_
            )
          },
          numeric(1)
        ),
        y = vapply(
          rows,
          function(row) {
            upload_scalar_numeric(
              get_value(
                row,
                mapping$y,
                NA_real_
              ),
              NA_real_
            )
          },
          numeric(1)
        ),
        facet = vapply(
          rows,
          function(row) {
            upload_scalar_character(
              get_value(
                row,
                mapping$facet,
                ""
              ),
              ""
            )
          },
          character(1)
        ),
        stringsAsFactors = FALSE
      )
      
      examples$faceted_scatter <- examples$faceted_scatter[
        is.finite(examples$faceted_scatter$x) &
          is.finite(examples$faceted_scatter$y) &
          nzchar(examples$faceted_scatter$facet),
        ,
        drop = FALSE
      ]
      facet_order <- unlist(content$facets$order, use.names = FALSE)
      if (length(facet_order) > 0) {
        examples$faceted_scatter$facet <- factor(
          examples$faceted_scatter$facet, levels = facet_order)
      }
    } else if (identical(graph_type, "density")) {
      x_key <- mapping$x
      
      examples$density <- data.frame(
        tempo_cir = vapply(
          rows,
          function(row) {
            as.numeric(get_value(row, x_key))
          },
          numeric(1)
        ),
        tecnica = vapply(
          rows,
          get_series_name,
          character(1)
        ),
        stringsAsFactors = FALSE
      )
    } else if (identical(graph_type, "scatter")) {
      examples$scatter <- data.frame(
        x = vapply(
          rows,
          function(row) {
            as.numeric(get_value(row, mapping$x))
          },
          numeric(1)
        ),
        y = vapply(
          rows,
          function(row) {
            as.numeric(get_value(row, mapping$y))
          },
          numeric(1)
        ),
        group = vapply(
          rows,
          get_series_name,
          character(1)
        ),
        stringsAsFactors = FALSE
      )
    } else if (identical(graph_type, "histogram")) {
      examples$histogram <- data.frame(
        value = vapply(
          rows,
          function(row) {
            as.numeric(get_value(row, mapping$x))
          },
          numeric(1)
        )
      )
    } else if (identical(graph_type, "boxplot")) {
      examples$boxplot <- data.frame(
        tecnica = vapply(
          rows,
          function(row) {
            as.character(
              get_value(
                row,
                mapping$x,
                ""
              )
            )
          },
          character(1)
        ),
        tempo_cir = vapply(
          rows,
          function(row) {
            as.numeric(
              get_value(
                row,
                mapping$y
              )
            )
          },
          numeric(1)
        ),
        group = vapply(
          rows,
          get_series_name,
          character(1)
        ),
        stringsAsFactors = FALSE
      )
    } else if (identical(graph_type, "stacked_bar_percent")) {
      examples$stacked_bar_percent <- data.frame(
        tecnica = vapply(
          rows,
          function(row) {
            as.character(
              get_value(row, mapping$x, "")
            )
          },
          character(1)
        ),
        series_id = vapply(
          rows,
          function(row) {
            as.character(
              get_value(row, "series_id", "")
            )
          },
          character(1)
        ),
        stringsAsFactors = FALSE
      )
    } else if (identical(graph_type, "pie")) {
      examples$pie <- data.frame(
        category = vapply(
          rows,
          function(row) {
            if (identical(mapping$category, "series_id")) {
              return(get_series_name(row))
            }
            
            as.character(
              get_value(
                row,
                mapping$category,
                ""
              )
            )
          },
          character(1)
        ),
        value = vapply(
          rows,
          function(row) {
            as.numeric(
              get_value(
                row,
                mapping$value
              )
            )
          },
          numeric(1)
        ),
        stringsAsFactors = FALSE
      )
    }
    
    examples
  })
  
  
  
