  sanitize_series_id <- function(value) {
    result <- tolower(value)
    result <- iconv(
      result,
      from = "",
      to = "ASCII//TRANSLIT"
    )
    result <- gsub("[^a-z0-9]+", "_", result)
    result <- gsub("^_+|_+$", "", result)
    
    if (!nzchar(result)) {
      result <- "series"
    }
    
    result
  }
  
  
