  graph_palette_values <- function(name, count) {
    if (count <= 0) {
      return(character(0))
    }
    
    base_default <- c(
      "#315A7D",
      "#B42318",
      "#18794E",
      "#7C3AED",
      "#D97706",
      "#0891B2",
      "#BE185D",
      "#4B5563"
    )
    
    values <- switch(
      name,
      colorblind = c(
        "#0072B2",
        "#E69F00",
        "#009E73",
        "#CC79A7",
        "#56B4E9",
        "#D55E00",
        "#F0E442",
        "#000000"
      ),
      viridis = grDevices::hcl.colors(
        count,
        palette = "Viridis"
      ),
      pastel = grDevices::hcl.colors(
        count,
        palette = "Pastel 1"
      ),
      dark = grDevices::hcl.colors(
        count,
        palette = "Dark 3"
      ),
      base_default
    )
    
    rep(values, length.out = count)
  }
  
  
