  tracked_graph_snapshot <- debounce(graph_snapshot, 500)
  
  
  observeEvent(
    tracked_graph_snapshot(),
    {
      if (graph_restoring_snapshot()) {
        return()
      }
      
      new_snapshot <- tracked_graph_snapshot()
      old_snapshot <- graph_last_snapshot()
      
      if (
        !is.null(old_snapshot) &&
        !identical(
          new_snapshot$source,
          old_snapshot$source
        )
      ) {
        reset_graph_history(new_snapshot)
        return()
      }
      
      if (is.null(old_snapshot)) {
        graph_last_snapshot(new_snapshot)
        graph_default_snapshot_value(new_snapshot)
        return()
      }
      
      if (!identical(new_snapshot, old_snapshot)) {
        history <- graph_history_stack()
        history[[length(history) + 1]] <- old_snapshot
        
        graph_history_stack(history)
        graph_redo_stack(list())
        graph_last_snapshot(new_snapshot)
      }
    },
    ignoreInit = TRUE
  )
  
  
  observeEvent(input$graph_undo_change, {
    history <- graph_history_stack()
    
    if (length(history) == 0) {
      showNotification(
        "Não há alterações anteriores no gráfico para desfazer.",
        type = "message"
      )
      return()
    }
    
    current <- isolate(graph_snapshot())
    target <- history[[length(history)]]
    history <- history[-length(history)]
    
    redo <- graph_redo_stack()
    redo[[length(redo) + 1]] <- current
    
    graph_history_stack(history)
    graph_redo_stack(redo)
    apply_graph_snapshot(target)
  })
  
  
  observeEvent(input$graph_redo_change, {
    redo <- graph_redo_stack()
    
    if (length(redo) == 0) {
      showNotification(
        "Não há alterações no gráfico para refazer.",
        type = "message"
      )
      return()
    }
    
    current <- isolate(graph_snapshot())
    target <- redo[[length(redo)]]
    redo <- redo[-length(redo)]
    
    history <- graph_history_stack()
    history[[length(history) + 1]] <- current
    
    graph_history_stack(history)
    graph_redo_stack(redo)
    apply_graph_snapshot(target)
  })
  
  
