  axis_breaks <- function(min_value, max_value, step_value) {
    validate(
      need(
        is.finite(min_value) &&
          is.finite(max_value) &&
          is.finite(step_value),
        "Os valores dos eixos precisam ser numéricos."
      ),
      need(
        max_value > min_value,
        "O valor final do eixo deve ser maior que o inicial."
      ),
      need(
        step_value > 0,
        "O intervalo do eixo deve ser maior que zero."
      )
    )
    
    seq(
      from = min_value,
      to = max_value,
      by = step_value
    )
  }
  
  
