  parse_project_identification <- function(value) {
    value <- trimws(value)
    
    pattern <- paste0(
      "^\\[(PRJ-[0-9]{8}-[0-9]{4})\\]",
      "\\s+(.+)$"
    )
    
    match <- regexec(
      pattern,
      value,
      perl = TRUE
    )
    
    parts <- regmatches(
      value,
      match
    )[[1]]
    
    if (length(parts) != 3) {
      return(
        list(
          valid = FALSE,
          project_id = "",
          project_name = "",
          year = NA_integer_,
          error = paste(
            "Use o formato:",
            "[PRJ-AAAAMMDD-NNNN] NOME DO PROJETO"
          )
        )
      )
    }
    
    project_id <- parts[[2]]
    project_name <- trimws(parts[[3]])
    
    list(
      valid = nzchar(project_name),
      project_id = project_id,
      project_name = project_name,
      year = as.integer(
        substr(project_id, 5, 8)
      ),
      error = if (nzchar(project_name)) {
        NULL
      } else {
        "O nome do projeto não pode ficar vazio."
      }
    )
  }
  
  
