  normalize_index_artifact_collection <- function(records) {
    if (is.null(records) || length(records) == 0) {
      return(list())
    }
    
    result <- lapply(
      records,
      function(record) {
        latest_version <- record$latest_version
        
        if (is.null(latest_version)) {
          versions <- as.integer(
            unlist(
              record$versions,
              use.names = FALSE
            )
          )
          
          latest_version <- if (length(versions) == 0) {
            1L
          } else {
            max(versions)
          }
        }
        
        versions <- as.integer(
          unlist(
            record$versions,
            use.names = FALSE
          )
        )
        
        if (length(versions) == 0) {
          versions <- seq_len(
            as.integer(latest_version)
          )
        }
        
        list(
          title = if (is.null(record$title)) {
            record$id
          } else {
            as.character(record$title)
          },
          latest_version = as.integer(latest_version),
          versions = sort(
            unique(versions)
          ),
          type = record$type
        )
      }
    )
    
    ids <- vapply(
      records,
      function(record) {
        as.character(record$id)
      },
      character(1)
    )
    
    stats::setNames(
      result,
      ids
    )
  }
  
  
  convert_github_index_to_project_index <- function(index) {
    projects <- index$projects
    
    if (is.null(projects) || length(projects) == 0) {
      return(
        stats::setNames(
          list(),
          character(0)
        )
      )
    }
    
    result <- lapply(
      projects,
      function(project) {
        list(
          title = as.character(project$project_name),
          analyst = as.character(project$analyst),
          tables = normalize_index_artifact_collection(
            project$tables
          ),
          figures = normalize_index_artifact_collection(
            project$figures
          )
        )
      }
    )
    
    project_ids <- vapply(
      projects,
      function(project) {
        as.character(project$project_id)
      },
      character(1)
    )
    
    stats::setNames(
      result,
      project_ids
    )
  }
  
  
  github_read_public_index <- function() {
    temp_file <- tempfile(fileext = ".json")
    
    on.exit(
      unlink(temp_file),
      add = TRUE
    )
    
    tryCatch(
      {
        utils::download.file(
          url = github_raw_index_url(),
          destfile = temp_file,
          mode = "wb",
          quiet = TRUE
        )
      },
      error = function(error) {
        stop(
          paste(
            "Falha ao baixar data/index.json:",
            conditionMessage(error)
          )
        )
      }
    )
    
    if (
      !file.exists(temp_file) ||
      file.info(temp_file)$size <= 0
    ) {
      stop("O GitHub retornou um index.json vazio.")
    }
    
    response_text <- paste(
      readLines(
        temp_file,
        warn = FALSE,
        encoding = "UTF-8"
      ),
      collapse = "\n"
    )
    
    index <- jsonlite::fromJSON(
      response_text,
      simplifyVector = FALSE
    )
    
    if (is.null(index$projects)) {
      stop(
        paste(
          "O arquivo data/index.json foi encontrado,",
          "mas não possui o campo projects."
        )
      )
    }
    
    index
  }
  
  
  
  load_github_index <- function(
    show_success_notification = FALSE
  ) {
    github_index_status_value(
      list(
        state = "loading",
        message = "Carregando..."
      )
    )
    
    tryCatch(
      {
        index <- github_read_public_index()
        converted <- convert_github_index_to_project_index(
          index
        )
        
        active_project_index(converted)
        github_full_index(index)
        
        project_count <- length(converted)
        
        github_index_status_value(
          list(
            state = "success",
            message = if (project_count == 0) {
              "GitHub conectado · nenhum projeto"
            } else {
              paste0(
                "GitHub conectado · ",
                project_count,
                if (project_count == 1) {
                  " projeto"
                } else {
                  " projetos"
                }
              )
            }
          )
        )
        
        if (isTRUE(show_success_notification)) {
          showNotification(
            "O índice de projetos foi atualizado.",
            type = "message",
            duration = 4
          )
        }
        
        invisible(index)
      },
      error = function(error) {
        github_index_status_value(
          list(
            state = "error",
            message = "Falha ao carregar o GitHub"
          )
        )
        
        showNotification(
          paste(
            "Não foi possível ler data/index.json:",
            conditionMessage(error),
            "No Shinylive, abra o app por HTTP/HTTPS,",
            "não diretamente como arquivo file://."
          ),
          type = "error",
          duration = 8
        )
        
        invisible(NULL)
      }
    )
  }
  
  
