  github_authenticated_request <- function(url) {
    config <- github_write_configuration()
    
    if (!isTRUE(config$valid)) {
      stop(
        paste(
          config$problems,
          collapse = " "
        )
      )
    }
    
    httr2::request(url) |>
      httr2::req_headers(
        Accept = "application/vnd.github+json",
        `X-GitHub-Api-Version` = "2022-11-28"
      ) |>
      httr2::req_auth_bearer_token(
        config$token
      ) |>
      httr2::req_user_agent(
        "stat-artifacts-dashboard/1.0"
      ) |>
      httr2::req_timeout(
        seconds = 30
      )
  }
  
  
  github_get_file_metadata <- function(path) {
    config <- github_write_configuration()
    
    request <- github_authenticated_request(
      github_api_contents_url(path)
    ) |>
      httr2::req_url_query(
        ref = config$branch
      ) |>
      httr2::req_error(
        is_error = function(response) {
          FALSE
        }
      )
    
    response <- httr2::req_perform(request)
    status <- httr2::resp_status(response)
    
    if (identical(status, 404L)) {
      return(NULL)
    }
    
    if (status >= 400) {
      body <- tryCatch(
        httr2::resp_body_string(response),
        error = function(error) ""
      )
      
      stop(
        paste(
          "Falha ao consultar o arquivo no GitHub.",
          "Status:",
          status,
          body
        )
      )
    }
    
    httr2::resp_body_json(
      response,
      simplifyVector = FALSE
    )
  }
  
  
  github_put_json_file <- function(
    path,
    object,
    commit_message
  ) {
    config <- github_write_configuration()
    metadata <- github_get_file_metadata(path)
    
    json_text <- as.character(
      jsonlite::toJSON(
        object,
        pretty = TRUE,
        auto_unbox = TRUE,
        null = "null",
        na = "null"
      )
    )
    
    encoded_content <- jsonlite::base64_enc(
      charToRaw(
        enc2utf8(json_text)
      )
    )
    
    body <- list(
      message = commit_message,
      content = encoded_content,
      branch = config$branch
    )
    
    if (
      !is.null(metadata) &&
      !is.null(metadata$sha)
    ) {
      body$sha <- metadata$sha
    }
    
    request <- github_authenticated_request(
      github_api_contents_url(path)
    ) |>
      httr2::req_method("PUT") |>
      httr2::req_body_json(
        body,
        auto_unbox = TRUE
      ) |>
      httr2::req_error(
        is_error = function(response) {
          FALSE
        }
      )
    
    response <- httr2::req_perform(request)
    status <- httr2::resp_status(response)
    
    if (!status %in% c(200L, 201L)) {
      response_body <- tryCatch(
        httr2::resp_body_string(response),
        error = function(error) ""
      )
      
      stop(
        paste(
          "O GitHub recusou a gravação.",
          "Status:",
          status,
          response_body
        )
      )
    }
    
    result <- httr2::resp_body_json(
      response,
      simplifyVector = FALSE
    )
    
    list(
      created = identical(status, 201L),
      status = status,
      result = result
    )
  }
  
  
  
  
  github_delete_file <- function(
    path,
    commit_message
  ) {
    config <- github_write_configuration()
    metadata <- github_get_file_metadata(path)
    
    if (is.null(metadata) || is.null(metadata$sha)) {
      return(list(deleted = FALSE, missing = TRUE))
    }
    
    response <- github_authenticated_request(
      github_api_contents_url(path)
    ) |>
      httr2::req_method("DELETE") |>
      httr2::req_body_json(
        list(
          message = commit_message,
          sha = metadata$sha,
          branch = config$branch
        ),
        auto_unbox = TRUE
      ) |>
      httr2::req_error(
        is_error = function(response) FALSE
      ) |>
      httr2::req_perform()
    
    status <- httr2::resp_status(response)
    
    if (!status %in% c(200L, 204L)) {
      stop(
        paste(
          "O GitHub recusou a exclusão. Status:",
          status,
          httr2::resp_body_string(response)
        )
      )
    }
    
    list(deleted = TRUE, missing = FALSE)
  }
  
  
  
