  upload_artifact_prefix <- reactive({
    if (identical(input$upload_artifact_type, "table")) {
      "TAB"
    } else {
      "FIG"
    }
  })
  
  
  next_upload_artifact_id <- reactive({
    collection <- upload_artifact_collection()
    prefix <- upload_artifact_prefix()
    existing_ids <- names(collection)
    
    if (
      identical(
        input$upload_project_mode,
        "new"
      ) &&
      is.null(upload_project_record())
    ) {
      return(
        sprintf(
          "%s-%03d",
          prefix,
          1L
        )
      )
    }
    
    if (length(existing_ids) == 0) {
      next_number <- 1L
    } else {
      numbers <- suppressWarnings(
        as.integer(
          sub(
            paste0("^", prefix, "-"),
            "",
            existing_ids
          )
        )
      )
      
      numbers <- numbers[is.finite(numbers)]
      
      next_number <- if (length(numbers) == 0) {
        1L
      } else {
        max(numbers) + 1L
      }
    }
    
    sprintf(
      "%s-%03d",
      prefix,
      next_number
    )
  })
  
  
