  normalize_upload_table <- function(object) {
    if (is.null(object$format_version)) {
      object$format_version <- "1.0"
    }
    
    if (is.null(object$columns)) {
      object$columns <- list()
    }
    
    object$columns <- lapply(
      object$columns,
      function(column) {
        if (is.null(column$visible)) {
          column$visible <- TRUE
        }
        
        column
      }
    )
    
    if (is.null(object$rows)) {
      object$rows <- list()
    }
    
    column_ids <- vapply(
      object$columns,
      function(column) {
        as.character(column$id)
      },
      character(1)
    )
    
    object$rows <- lapply(
      seq_along(object$rows),
      function(index) {
        row <- object$rows[[index]]
        
        if (is.null(row$id) || !nzchar(as.character(row$id))) {
          row$id <- sprintf("row_%03d", index)
        }
        
        if (is.null(row$type)) {
          row$type <- "data"
        }
        
        if (is.null(row$level)) {
          row$level <- 0L
        }
        
        if (is.null(row$parent_id)) {
          row$parent_id <- NULL
        }
        
        if (is.null(row$cells) && !is.null(row$values)) {
          row$cells <- row$values
        }
        
        if (is.null(row$cells)) {
          row$cells <- list()
        }
        
        for (column_id in column_ids) {
          cell <- row$cells[[column_id]]
          
          if (is.null(cell)) {
            cell <- list(value = "")
          } else if (!is.list(cell)) {
            cell <- list(value = as.character(cell))
          }
          
          if (is.null(cell$value)) {
            cell$value <- ""
          }
          
          if (is.null(cell$footnote_ids)) {
            cell$footnote_ids <- character(0)
          }
          
          row$cells[[column_id]] <- cell
        }
        
        row
      }
    )
    
    if (is.null(object$footnotes)) {
      object$footnotes <- list()
    }
    
    object
  }
  
  
  upload_scalar_numeric <- function(
