      return(default)
    }
    
    as.character(value[[1]])
  }
  
  
  normalize_upload_figure <- function(object) {
    if (is.null(object$format_version)) {
      object$format_version <- "1.0"
    }
    
    if (is.null(object$type) && !is.null(object$chart_type)) {
      object$type <- object$chart_type
    }
    
    # Compatibilidade com nomes usados pelo Gemini.
    object$type <- canonical_graph_type(
      graph_type = object$type,
      mapping = object$mapping
    )
    
    if (is.null(object$options) && !is.null(object$parameters)) {
      object$options <- object$parameters
    }
    
    if (is.null(object$options)) {
      object$options <- list()
    }
    
    if (is.null(object$mapping)) {
      object$mapping <- list()
    }
    
    if (!is.null(object$mapping$group)) {
      object$mapping$series <- "series_id"
    }
    
    if (is.null(object$series)) {
      object$series <- list()
    }
    
    default_series_colors <- c(
      "#315A7D",
      "#B42318",
      "#18794E",
      "#7C3AED",
      "#D97706",
      "#0891B2",
      "#BE185D",
      "#4B5563"
    )
    
    object$series <- lapply(
      seq_along(object$series),
      function(index) {
        series <- object$series[[index]]
        
        if (is.null(series$visible)) {
          series$visible <- TRUE
        }
        
        if (
          is.null(series$name) ||
          !nzchar(as.character(series$name))
        ) {
          series$name <- if (
            is.null(series$source_name)
          ) {
            paste("Série", index)
          } else {
            series$source_name
          }
        }
        
        if (
          is.null(series$color) ||
          !nzchar(as.character(series$color))
        ) {
          series$color <- default_series_colors[[
            ((index - 1) %% length(default_series_colors)) + 1
          ]]
        }
        
        series
      }
    )
    
    if (is.null(object$data)) {
      object$data <- list()
    }
    
    object$data <- lapply(
      seq_along(object$data),
      function(index) {
        observation <- object$data[[index]]
        
        if (is.null(observation$observation_id)) {
          observation$observation_id <- sprintf(
            "obs_%03d",
            index
          )
        }
        
        observation
      }
    )
    
    if (identical(object$type, "density")) {
      if (is.null(object$options$alpha)) {
        object$options$alpha <- 0.4
      }
      
      if (is.null(object$options$adjust)) {
        object$options$adjust <- 1
      }
      
      if (is.null(object$options$show_line)) {
        object$options$show_line <- TRUE
      }
    }
    
    if (identical(object$type, "faceted_scatter")) {
      if (is.null(object$facets)) {
        object$facets <- list()
      }
      
      # O Gemini pode colocar scales dentro de parameters.
      if (
        is.null(object$facets$scales) &&
        !is.null(object$options$scales)
      ) {
        object$facets$scales <- object$options$scales
      }
      
      if (is.null(object$options$point_size)) object$options$point_size <- 3
      if (is.null(object$options$point_stroke)) object$options$point_stroke <- 1.2
      if (is.null(object$options$point_fill)) object$options$point_fill <- "#e2e8f0"
      if (is.null(object$options$point_color)) object$options$point_color <- "#0f172a"
      if (is.null(object$facets$scales)) object$facets$scales <- "free_x"
      if (is.null(object$facets$ncol)) object$facets$ncol <- 3
    }
    
    if (identical(object$type, "boxplot")) {
      if (is.null(object$options$width)) {
        object$options$width <- 0.6
      }
      
      if (is.null(object$options$alpha)) {
        object$options$alpha <- 0.8
      }
      
      if (is.null(object$options$outlier_shape)) {
        object$options$outlier_shape <- 16
      }
      
      if (is.null(object$options$outlier_size)) {
        object$options$outlier_size <- 2
      }
      
      if (is.null(object$options$outlier_color)) {
        object$options$outlier_color <- "black"
      }
      
      if (is.null(object$options$show_legend)) {
        object$options$show_legend <- FALSE
      }
    }
    
    if (identical(object$type, "stacked_bar_percent")) {
      if (is.null(object$options$position)) {
        object$options$position <- "fill"
      }
      
      if (is.null(object$options$width)) {
        object$options$width <- 0.5
      }
    }
    
    object
  }
  
  
  validate_upload_table <- function(object) {
    problems <- character(0)
    successes <- character(0)
    
    if (is.null(object$title) || !nzchar(trimws(object$title))) {
      problems <- c(problems, "A tabela não possui título.")
    } else {
      successes <- c(successes, "Título da tabela encontrado.")
    }
    
    if (length(object$columns) == 0) {
      problems <- c(problems, "A tabela não possui colunas.")
      return(list(problems = problems, successes = successes))
    }
    
    column_ids <- vapply(
      object$columns,
      function(column) as.character(column$id),
      character(1)
    )
    
    if (any(!nzchar(column_ids))) {
      problems <- c(problems, "Existe coluna sem ID.")
    }
    
    if (anyDuplicated(column_ids)) {
      problems <- c(problems, "Os IDs das colunas não são únicos.")
    } else {
      successes <- c(successes, "IDs das colunas são únicos.")
    }
    
    if (length(object$rows) == 0) {
      problems <- c(problems, "A tabela não possui linhas.")
      return(list(problems = problems, successes = successes))
    }
    
    row_ids <- vapply(
      object$rows,
      function(row) as.character(row$id),
      character(1)
    )
    
    if (anyDuplicated(row_ids)) {
      problems <- c(problems, "Os IDs das linhas não são únicos.")
    } else {
      successes <- c(successes, "IDs das linhas são únicos.")
    }
    
    parent_ids <- vapply(
      object$rows,
      function(row) {
        if (is.null(row$parent_id)) "" else as.character(row$parent_id)
      },
      character(1)
    )
    
    invalid_parents <- setdiff(
      unique(parent_ids[nzchar(parent_ids)]),
      row_ids
    )
    
    if (length(invalid_parents) > 0) {
      problems <- c(
        problems,
        paste(
          "parent_id inexistente:",
          paste(invalid_parents, collapse = ", ")
        )
      )
    } else {
      successes <- c(successes, "Hierarquia das linhas é válida.")
    }
    
    valid_row_types <- c("data", "group")
    row_types <- vapply(
      object$rows,
      function(row) as.character(row$type),
      character(1)
    )
    
    invalid_types <- setdiff(unique(row_types), valid_row_types)
    
    if (length(invalid_types) > 0) {
      problems <- c(
        problems,
        paste(
          "Tipos de linha não reconhecidos:",
          paste(invalid_types, collapse = ", ")
        )
      )
    }
    
    footnote_ids <- vapply(
      object$footnotes,
      function(note) as.character(note$id),
      character(1)
    )
    
    used_footnotes <- unlist(
      lapply(
        object$rows,
        function(row) {
          unlist(
            lapply(
              row$cells,
              function(cell) cell$footnote_ids
            ),
            use.names = FALSE
          )
        }
      ),
      use.names = FALSE
    )
    
    invalid_footnotes <- setdiff(
      unique(used_footnotes),
      footnote_ids
    )
    
    if (length(invalid_footnotes) > 0) {
      problems <- c(
        problems,
        paste(
          "Notas referenciadas não existem:",
          paste(invalid_footnotes, collapse = ", ")
        )
      )
    } else {
      successes <- c(successes, "Referências de notas são válidas.")
    }
    
    list(problems = problems, successes = successes)
  }
  
  
  validate_upload_figure <- function(object) {
    problems <- character(0)
    successes <- character(0)
    
    supported_types <- c(
      "scatter",
      "histogram",
      "pie",
      "density",
      "boxplot",
      "stacked_bar_percent",
      "faceted_scatter"
    )
    
    if (is.null(object$type) || !object$type %in% supported_types) {
      problems <- c(
        problems,
        paste(
          "Tipo de gráfico não suportado.",
          "Use scatter, faceted_scatter, histogram, pie, density, boxplot ou stacked_bar_percent."
        )
      )
    } else {
      successes <- c(
        successes,
        paste("Tipo de gráfico reconhecido:", object$type)
      )
      
      if (
        !is.null(parsed_upload_content()$type) &&
        !identical(
          as.character(parsed_upload_content()$type),
          as.character(object$type)
        )
      ) {
        successes <- c(
          successes,
          paste0(
            "Tipo normalizado de ",
            parsed_upload_content()$type,
            " para ",
            object$type,
            "."
          )
        )
      }
    }
    
    if (length(object$data) == 0) {
      problems <- c(problems, "O gráfico não possui dados reais.")
    } else {
      successes <- c(
        successes,
        paste(length(object$data), "observações encontradas.")
      )
    }
    
    series_ids <- vapply(
      object$series,
      function(series) as.character(series$id),
      character(1)
    )
    
    if (anyDuplicated(series_ids)) {
      problems <- c(problems, "Os IDs das séries não são únicos.")
    } else if (length(series_ids) > 0) {
      successes <- c(successes, "IDs das séries são únicos.")
    }
    
    data_series_ids <- vapply(
      object$data,
      function(observation) {
        if (is.null(observation$series_id)) "" else as.character(observation$series_id)
      },
      character(1)
    )
    
    invalid_series <- setdiff(
      unique(data_series_ids[nzchar(data_series_ids)]),
      series_ids
    )
    
    if (length(invalid_series) > 0) {
      problems <- c(
        problems,
        paste(
          "Séries dos dados não foram declaradas:",
          paste(invalid_series, collapse = ", ")
        )
      )
    }
    
    required_fields <- switch(
      object$type,
      scatter = c("x", "y"),
      faceted_scatter = c(
        object$mapping$x,
        object$mapping$y,
        object$mapping$facet
      ),
      histogram = c("value"),
      pie = c("series_id", "value"),
      density = c(object$mapping$x, "series_id"),
      boxplot = c(
        object$mapping$x,
        object$mapping$y,
        "series_id"
      ),
      stacked_bar_percent = c(
        object$mapping$x,
        "series_id"
      ),
      character(0)
    )
    
    if (length(object$data) > 0 && length(required_fields) > 0) {
      missing_fields <- unique(
        unlist(
          lapply(
            object$data,
            function(observation) {
              required_fields[
                !required_fields %in% names(observation)
              ]
            }
          ),
          use.names = FALSE
        )
      )
      
      if (length(missing_fields) > 0) {
        problems <- c(
          problems,
          paste(
            "Campos ausentes nos dados:",
            paste(missing_fields, collapse = ", ")
          )
        )
      } else {
        successes <- c(successes, "Campos obrigatórios estão presentes.")
      }
    }
    
    list(problems = problems, successes = successes)
  }
  
  
  parsed_upload_content <- reactiveVal(NULL)
  normalized_upload_content <- reactiveVal(NULL)
  
  
  observeEvent(input$validate_upload, {
    problems <- character(0)
    successes <- character(0)
    
    parsed_upload_content(NULL)
    normalized_upload_content(NULL)
    
    content <- trimws(input$upload_content)
    project_id <- selected_upload_project_id()
    project_name <- selected_upload_project_name()
    analyst <- selected_upload_analyst()
    artifact_id <- selected_upload_artifact_id()
    version <- selected_upload_version()
    
    if (
      identical(
        input$upload_project_mode,
        "new"
      ) &&
      !isTRUE(parsed_new_project()$valid)
    ) {
      problems <- c(
        problems,
        parsed_new_project()$error
      )
    }
    
    if (!nzchar(project_id)) {
      problems <- c(
        problems,
        "Informe ou selecione o código do projeto."
      )
    } else if (
      !grepl(
        "^PRJ-[0-9]{8}-[0-9]{4}$",
        project_id
      )
    ) {
      problems <- c(
        problems,
        "O projeto deve seguir o padrão PRJ-AAAAMMDD-NNNN."
      )
    } else {
      successes <- c(successes, "Código do projeto reconhecido.")
    }
    
    if (!nzchar(project_name)) {
      problems <- c(problems, "Informe o nome do projeto.")
    } else {
      successes <- c(successes, "Nome do projeto reconhecido.")
    }
    
    if (
      identical(input$upload_project_mode, "new") &&
      nzchar(project_id) &&
      project_id %in% names(active_project_index())
    ) {
      problems <- c(
        problems,
        "Esse código já existe. Selecione Projeto existente."
      )
    }
    
    if (
      identical(input$upload_project_mode, "existing") &&
      is.null(upload_project_record())
    ) {
      problems <- c(
        problems,
        "O projeto selecionado não foi localizado no índice."
      )
    }
    
    if (
      identical(input$upload_project_mode, "new") &&
      identical(input$upload_artifact_mode, "existing")
    ) {
      problems <- c(
        problems,
        "Um projeto novo não pode possuir artefato existente."
      )
    }
    
    if (is.null(artifact_id) || !nzchar(artifact_id)) {
      problems <- c(problems, "Não foi possível definir o ID do artefato.")
    } else {
      successes <- c(successes, paste("Destino definido:", artifact_id))
    }
    
    if (is.na(version)) {
      problems <- c(problems, "Não foi possível calcular a próxima versão.")
    } else {
      successes <- c(successes, paste("Versão calculada:", version))
    }
    
    object <- NULL
    
    if (!nzchar(content)) {
      problems <- c(problems, "Cole o conteúdo para upload.")
    } else {
      object <- tryCatch(
        jsonlite::fromJSON(
          content,
          simplifyVector = FALSE
        ),
        error = function(error) {
          problems <<- c(
            problems,
            paste("JSON inválido:", error$message)
          )
          NULL
        }
      )
    }
    
    if (!is.null(object)) {
      parsed_upload_content(object)
      successes <- c(successes, "JSON válido e interpretado.")
      
      if (identical(input$upload_artifact_type, "table")) {
        object <- normalize_upload_table(object)
        validation <- validate_upload_table(object)
      } else {
        object <- normalize_upload_figure(object)
        validation <- validate_upload_figure(object)
      }
      
      problems <- c(problems, validation$problems)
      successes <- c(successes, validation$successes)
      normalized_upload_content(object)
    }
    
    upload_validation_message(
      list(
        successes = unique(successes),
        problems = unique(problems),
        destination = list(
          project_id = project_id,
          project_name = project_name,
          analyst = analyst,
          artifact_id = artifact_id,
          version = version
        )
      )
    )
  })
  
  
