  upload_table_preview_ui <- reactive({
    object <- normalized_upload_content()
    req(object)
    
    column_ids <- vapply(
      object$columns,
      function(column) as.character(column$id),
      character(1)
    )
    
    visible_columns <- Filter(
      function(column) isTRUE(column$visible),
      object$columns
    )
    
    visible_ids <- vapply(
      visible_columns,
      function(column) as.character(column$id),
      character(1)
    )
    
    note_map <- stats::setNames(
      object$footnotes,
      vapply(
        object$footnotes,
        function(note) as.character(note$id),
        character(1)
      )
    )
    
    header <- tags$tr(
      lapply(
        visible_columns,
        function(column) tags$th(column$name)
      )
    )
    
    body <- lapply(
      object$rows,
      function(row) {
        tags$tr(
          class = if (identical(row$type, "group")) {
            "fw-bold"
          } else {
            NULL
          },
          
          lapply(
            visible_ids,
            function(column_id) {
              cell <- row$cells[[column_id]]
              value <- as.character(cell$value)
              
              footnote_symbols <- vapply(
                cell$footnote_ids,
                function(note_id) {
                  note <- note_map[[note_id]]
                  if (is.null(note)) {
                    note_id
                  } else if (!is.null(note$symbol)) {
                    as.character(note$symbol)
                  } else {
                    as.character(note$id)
                  }
                },
                character(1)
              )
              
              content <- tagList(
                if (
                  identical(column_id, column_ids[[1]]) &&
                  as.integer(row$level) > 0
                ) {
                  tags$span(
                    style = paste0(
                      "display:inline-block;padding-left:",
                      as.integer(row$level) * 18,
                      "px;"
                    ),
                    value
                  )
                } else {
                  value
                },
                if (length(footnote_symbols) > 0) {
                  tags$sup(paste0(footnote_symbols, collapse = ","))
                }
              )
              
              tags$td(content)
            }
          )
        )
      }
    )
    
    footnotes <- if (length(object$footnotes) > 0) {
      tags$div(
        class = "mt-3 small fst-italic",
        lapply(
          object$footnotes,
          function(note) {
            tags$div(
              tags$sup(
                if (is.null(note$symbol)) note$id else note$symbol
              ),
              paste0(" ", note$text)
            )
          }
        )
      )
    } else {
      NULL
    }
    
    div(
      class = "editor-card mt-3",
      h4("Pré-visualização da tabela importada"),
      h5(object$title),
      tags$div(
        class = "table-responsive",
        tags$table(
          class = "table table-bordered table-striped align-middle",
          tags$thead(header),
          tags$tbody(body)
        )
      ),
      footnotes
    )
  })
  
  
  upload_figure_object <- reactive({
    object <- normalized_upload_content()
    req(object)
    
    series_map <- stats::setNames(
      object$series,
      vapply(
        object$series,
        function(series) as.character(series$id),
        character(1)
      )
    )
    
    visible_series <- Filter(
      function(series) isTRUE(series$visible),
      object$series
    )
    
    preview_palette <- c(
      "#315A7D",
      "#B42318",
      "#18794E",
      "#7C3AED",
      "#D97706",
      "#0891B2",
      "#BE185D",
      "#4B5563"
    )
    
    series_colors <- stats::setNames(
      vapply(
        seq_along(visible_series),
        function(index) {
          series <- visible_series[[index]]
          
          if (
            is.null(series$color) ||
            !nzchar(as.character(series$color))
          ) {
            return(
              preview_palette[[
                ((index - 1) %% length(preview_palette)) + 1
              ]]
            )
          }
          
          as.character(series$color)
        },
        character(1)
      ),
      vapply(
        seq_along(visible_series),
        function(index) {
          series <- visible_series[[index]]
          
          if (
            is.null(series$name) ||
            !nzchar(as.character(series$name))
          ) {
            return(paste("Série", index))
          }
          
          as.character(series$name)
        },
        character(1)
      )
    )
    
    data <- object$data
    
    if (identical(object$type, "density")) {
      x_key <- object$mapping$x
      
      frame <- data.frame(
        x = vapply(
          data,
          function(row) as.numeric(row[[x_key]]),
          numeric(1)
        ),
        series_id = vapply(
          data,
          function(row) as.character(row$series_id),
          character(1)
        ),
        stringsAsFactors = FALSE
      )
      
      frame <- frame[
        vapply(
          frame$series_id,
          function(id) isTRUE(series_map[[id]]$visible),
          logical(1)
        ),
        ,
        drop = FALSE
      ]
      
      frame$series_name <- vapply(
        frame$series_id,
        function(id) as.character(series_map[[id]]$name),
        character(1)
      )
      
      return(
        ggplot2::ggplot(
          frame,
          ggplot2::aes(
            x = x,
            fill = series_name,
            color = series_name
          )
        ) +
          ggplot2::geom_density(
            alpha = as.numeric(object$options$alpha),
            adjust = as.numeric(object$options$adjust),
            linewidth = if (isTRUE(object$options$show_line)) 0.7 else 0
          ) +
          ggplot2::scale_fill_manual(values = series_colors) +
          ggplot2::scale_color_manual(values = series_colors) +
          ggplot2::labs(
            title = object$title,
            x = x_key,
            y = "Densidade",
            fill = "Grupo",
            color = "Grupo"
          ) +
          ggplot2::theme_minimal()
      )
    }
    
    if (identical(object$type, "histogram")) {
      frame <- data.frame(
        value = vapply(
          data,
          function(row) as.numeric(row$value),
          numeric(1)
        )
      )
      
      return(
        ggplot2::ggplot(frame, ggplot2::aes(x = value)) +
          ggplot2::geom_histogram(
            bins = if (is.null(object$options$bins)) 10 else object$options$bins,
            fill = if (length(series_colors) > 0) series_colors[[1]] else "#315A7D",
            color = "white"
          ) +
          ggplot2::labs(title = object$title) +
          ggplot2::theme_minimal()
      )
    }
    
    if (identical(object$type, "faceted_scatter")) {
      x_key <- object$mapping$x
      y_key <- object$mapping$y
      facet_key <- object$mapping$facet
      
      frame <- data.frame(
        x_value = vapply(
          data,
          function(row) {
            upload_scalar_numeric(
              row[[x_key]],
              NA_real_
            )
          },
          numeric(1)
        ),
        y_value = vapply(
          data,
          function(row) {
            upload_scalar_numeric(
              row[[y_key]],
              NA_real_
            )
          },
          numeric(1)
        ),
        facet_value = vapply(
          data,
          function(row) {
            upload_scalar_character(
              row[[facet_key]],
              ""
            )
          },
          character(1)
        ),
        stringsAsFactors = FALSE
      )
      
      frame <- frame[
        is.finite(frame$x_value) &
          is.finite(frame$y_value) &
          nzchar(frame$facet_value),
        ,
        drop = FALSE
      ]
      
      if (nrow(frame) == 0) {
        stop(
          paste(
            "O faceted_scatter não possui observações completas",
            "após remover valores ausentes."
          )
        )
      }
      
      facet_order <- unlist(object$facets$order, use.names = FALSE)
      if (length(facet_order) > 0) {
        frame$facet_value <- factor(frame$facet_value, levels = facet_order)
      }
      
      graph <- ggplot2::ggplot(
        frame, ggplot2::aes(x = x_value, y = y_value)
      ) +
        ggplot2::geom_point(
          shape = 21,
          size = as.numeric(object$options$point_size),
          stroke = as.numeric(object$options$point_stroke),
          fill = as.character(object$options$point_fill),
          colour = as.character(object$options$point_color)
        ) +
        ggplot2::facet_wrap(
          ~ facet_value,
          scales = as.character(object$facets$scales),
          ncol = as.integer(object$facets$ncol)
        ) +
        ggplot2::labs(
          title = object$title,
          x = if (is.null(object$axes$x$title)) x_key else object$axes$x$title,
          y = if (is.null(object$axes$y$title)) y_key else object$axes$y$title
        ) +
        ggplot2::theme_bw() +
        ggplot2::theme(
          plot.margin = ggplot2::margin(
            t = 18,
            r = 24,
            b = 24,
            l = 24
          ),
          strip.text = ggplot2::element_text(
            margin = ggplot2::margin(
              t = 6,
              r = 6,
              b = 6,
              l = 6
            )
          )
        )
      
      horizontal_lines <- object$options$horizontal_lines
      if (!is.null(horizontal_lines) && length(horizontal_lines) > 0) {
        for (line in horizontal_lines) {
          graph <- graph + ggplot2::geom_hline(
            yintercept = as.numeric(line$y),
            colour = if (is.null(line$color)) "black" else as.character(line$color),
            linewidth = if (is.null(line$width)) 0.8 else as.numeric(line$width)
          )
        }
      }
      
      return(graph)
    }
    
    if (identical(object$type, "scatter")) {
      frame <- data.frame(
        x = vapply(data, function(row) as.numeric(row$x), numeric(1)),
        y = vapply(data, function(row) as.numeric(row$y), numeric(1)),
        series_id = vapply(
          data,
          function(row) {
            if (is.null(row$series_id)) "series" else as.character(row$series_id)
          },
          character(1)
        ),
        stringsAsFactors = FALSE
      )
      
      if (length(series_map) == 0) {
        series_map <- list(
          series = list(
            id = "series",
            name = "Série",
            color = "#315A7D",
            visible = TRUE
          )
        )
        series_colors <- c("Série" = "#315A7D")
      }
      
      frame$series_name <- vapply(
        frame$series_id,
        function(id) as.character(series_map[[id]]$name),
        character(1)
      )
      
      return(
        ggplot2::ggplot(
          frame,
          ggplot2::aes(x = x, y = y, color = series_name)
        ) +
          ggplot2::geom_point(size = 3) +
          ggplot2::scale_color_manual(values = series_colors) +
          ggplot2::labs(title = object$title, color = "Grupo") +
          ggplot2::theme_minimal()
      )
    }
    
    if (identical(object$type, "stacked_bar_percent")) {
      x_key <- object$mapping$x
      
      frame <- data.frame(
        x_value = vapply(
          data,
          function(row) as.character(row[[x_key]]),
          character(1)
        ),
        series_id = vapply(
          data,
          function(row) as.character(row$series_id),
          character(1)
        ),
        stringsAsFactors = FALSE
      )
      
      frame$series_name <- vapply(
        frame$series_id,
        function(series_id) {
          if (!is.null(series_map[[series_id]])) {
            return(as.character(series_map[[series_id]]$name))
          }
          
          series_id
        },
        character(1)
      )
      
      visible_names <- names(series_colors)
      
      if (length(visible_names) > 0) {
        frame <- frame[
          frame$series_name %in% visible_names,
          ,
          drop = FALSE
        ]
      }
      
      x_title <- if (!is.null(object$axes$x$title)) {
        as.character(object$axes$x$title)
      } else {
        x_key
      }
      
      y_title <- if (!is.null(object$axes$y$title)) {
        as.character(object$axes$y$title)
      } else {
        "Proporção (%)"
      }
      
      legend_title <- if (!is.null(object$legend$title)) {
        as.character(object$legend$title)
      } else {
        "Grupo"
      }
      
      graph <- ggplot2::ggplot(
        frame,
        ggplot2::aes(
          x = x_value,
          fill = series_name
        )
      ) +
        ggplot2::geom_bar(
          position = "fill",
          width = as.numeric(object$options$width)
        ) +
        ggplot2::scale_fill_manual(
          values = series_colors,
          drop = FALSE
        ) +
        ggplot2::scale_y_continuous(
          labels = function(x) paste0(round(x * 100), "%"),
          breaks = seq(0, 1, 0.2),
          limits = c(0, 1)
        ) +
        ggplot2::labs(
          title = object$title,
          x = x_title,
          y = y_title,
          fill = legend_title
        ) +
        ggplot2::theme_minimal()
      
      return(graph)
    }
    
    if (identical(object$type, "boxplot")) {
      x_key <- object$mapping$x
      y_key <- object$mapping$y
      
      frame <- data.frame(
        group_value = vapply(
          data,
          function(row) as.character(row[[x_key]]),
          character(1)
        ),
        y_value = vapply(
          data,
          function(row) as.numeric(row[[y_key]]),
          numeric(1)
        ),
        series_id = vapply(
          data,
          function(row) {
            if (is.null(row$series_id)) {
              ""
            } else {
              as.character(row$series_id)
            }
          },
          character(1)
        ),
        stringsAsFactors = FALSE
      )
      
      frame$series_name <- vapply(
        seq_len(nrow(frame)),
        function(index) {
          series_id <- frame$series_id[[index]]
          
          if (
            nzchar(series_id) &&
            !is.null(series_map[[series_id]])
          ) {
            return(
              as.character(
                series_map[[series_id]]$name
              )
            )
          }
          
          frame$group_value[[index]]
        },
        character(1)
      )
      
      visible_names <- names(series_colors)
      
      if (length(visible_names) > 0) {
        frame <- frame[
          frame$series_name %in% visible_names,
          ,
          drop = FALSE
        ]
      }
      
      x_title <- if (
        !is.null(object$axes$x$title)
      ) {
        as.character(object$axes$x$title)
      } else {
        x_key
      }
      
      y_title <- if (
        !is.null(object$axes$y$title)
      ) {
        as.character(object$axes$y$title)
      } else {
        y_key
      }
      
      graph <- ggplot2::ggplot(
        frame,
        ggplot2::aes(
          x = series_name,
          y = y_value,
          fill = series_name
        )
      ) +
        ggplot2::geom_boxplot(
          width = as.numeric(object$options$width),
          alpha = as.numeric(object$options$alpha),
          outlier.shape = as.numeric(
            object$options$outlier_shape
          ),
          outlier.size = as.numeric(
            object$options$outlier_size
          ),
          outlier.colour = as.character(
            object$options$outlier_color
          )
        ) +
        ggplot2::scale_fill_manual(
          values = series_colors,
          drop = FALSE
        ) +
        ggplot2::labs(
          title = object$title,
          x = x_title,
          y = y_title,
          fill = "Grupo"
        ) +
        ggplot2::theme_minimal()
      
      if (!isTRUE(object$options$show_legend)) {
        graph <- graph +
          ggplot2::theme(
            legend.position = "none"
          )
      }
      
      return(graph)
    }
    
    if (identical(object$type, "pie")) {
      frame <- data.frame(
        series_id = vapply(data, function(row) as.character(row$series_id), character(1)),
        value = vapply(data, function(row) as.numeric(row$value), numeric(1)),
        stringsAsFactors = FALSE
      )
      
      frame$series_name <- vapply(
        frame$series_id,
        function(id) as.character(series_map[[id]]$name),
        character(1)
      )
      
      return(
        ggplot2::ggplot(
          frame,
          ggplot2::aes(x = 1, y = value, fill = series_name)
        ) +
          ggplot2::geom_col(width = 1, color = "white") +
          ggplot2::coord_polar(theta = "y") +
          ggplot2::scale_fill_manual(values = series_colors) +
          ggplot2::labs(title = object$title, fill = "Categoria") +
          ggplot2::theme_void()
      )
    }
    
    NULL
  })
  
  
