      class = "structure-note",
      
      tags$strong("Digite exatamente:"),
      
      tags$br(),
      
      tags$code(code)
    )
  })
  
  
  base_download_index <- reactive({
    projects <- lapply(
      names(active_project_index()),
      function(project_id) {
        project <- active_project_index()[[project_id]]
        
        tables <- lapply(
          names(project$tables),
          function(artifact_id) {
            record <- project$tables[[artifact_id]]
            latest <- as.integer(record$latest_version)
            
            versions <- as.integer(record$versions)
            
            if (length(versions) == 0) {
              versions <- seq_len(latest)
            }
            
            list(
              id = artifact_id,
              title = record$title,
              latest_version = latest,
              versions = as.list(
                sort(
                  unique(versions)
                )
              )
            )
          }
        )
        
        figures <- lapply(
          names(project$figures),
          function(artifact_id) {
            record <- project$figures[[artifact_id]]
            latest <- as.integer(record$latest_version)
            
            versions <- as.integer(record$versions)
            
            if (length(versions) == 0) {
              versions <- seq_len(latest)
            }
            
            list(
              id = artifact_id,
              title = record$title,
              latest_version = latest,
              versions = as.list(
                sort(
                  unique(versions)
                )
              )
            )
          }
        )
        
        list(
          year = as.integer(
            substr(project_id, 5, 8)
          ),
          analyst = project$analyst,
          project_id = project_id,
          project_name = project$title,
          tables = tables,
          figures = figures
        )
      }
    )
    
    list(
      index_format_version = "1.0",
      projects = projects
    )
  })
  
  
  manage_delete_in_progress <- reactiveVal(FALSE)
  
  
  github_artifact_file_path <- function(
    project_id,
    artifact_type,
    artifact_id,
    version
  ) {
    folder <- if (
      identical(
        artifact_type,
        "table"
      )
    ) {
      "tables"
    } else {
      "figures"
    }
    
    paste0(
      "data/projects/",
      project_id,
      "/",
      folder,
      "/",
      artifact_id,
      "/v",
      sprintf(
        "%03d",
        as.integer(version)
      ),
      ".json"
    )
  }
  
  
  observeEvent(input$prepare_deletion, {
    req(!isTRUE(manage_delete_in_progress()))
    
    if (!github_admin_access_enabled()) {
      deletion_message(
        list(
          ok = FALSE,
          text = paste(
            "Modo somente leitura.",
            "A exclusão só está disponível na instalação administrativa local."
          )
        )
      )
      deletion_index_result(NULL)
      return()
    }
    
    expected <- deletion_confirmation_code()
    received <- trimws(input$manage_confirmation)
    
    if (
      is.null(expected) ||
      !nzchar(expected)
    ) {
      deletion_message(
        list(
          ok = FALSE,
          text = "Não foi possível definir o item a excluir."
        )
      )
      deletion_index_result(NULL)
      return()
    }
    
    if (!identical(received, expected)) {
      deletion_message(
        list(
          ok = FALSE,
          text = paste(
            "A confirmação não corresponde.",
            "Digite exatamente:",
            expected
          )
        )
      )
      deletion_index_result(NULL)
      return()
    }
    
    config <- github_write_configuration()
    
    if (!isTRUE(config$valid)) {
      deletion_message(
        list(
          ok = FALSE,
          text = paste(
            config$problems,
            collapse = " "
          )
        )
      )
      deletion_index_result(NULL)
      return()
    }
    
    index <- base_download_index()
    projects <- index$projects
    
    project_position <- which(
      vapply(
        projects,
        function(project) {
          identical(
            project$project_id,
            input$manage_project_id
          )
        },
        logical(1)
      )
    )
    
    if (length(project_position) == 0) {
      deletion_message(
        list(
          ok = FALSE,
          text = "Projeto não encontrado."
        )
      )
      deletion_index_result(NULL)
      return()
    }
    
    project_position <- project_position[[1]]
    project <- projects[[project_position]]
    
    paths_to_delete <- character(0)
    result_description <- ""
    
    if (identical(input$manage_delete_scope, "project")) {
      for (record in project$tables) {
        versions <- as.integer(
          unlist(
            record$versions,
            use.names = FALSE
          )
        )
        
        for (version in versions) {
          paths_to_delete <- c(
            paths_to_delete,
            github_artifact_file_path(
              project_id = project$project_id,
              artifact_type = "table",
              artifact_id = record$id,
              version = version
            )
          )
        }
      }
      
      for (record in project$figures) {
        versions <- as.integer(
          unlist(
            record$versions,
            use.names = FALSE
          )
        )
        
        for (version in versions) {
          paths_to_delete <- c(
            paths_to_delete,
            github_artifact_file_path(
              project_id = project$project_id,
              artifact_type = "figure",
              artifact_id = record$id,
              version = version
            )
          )
        }
      }
      
      projects <- projects[-project_position]
      
      result_description <- paste(
        "Projeto excluído:",
        project$project_id
      )
    } else {
      collection_name <- if (
        identical(input$manage_artifact_type, "table")
      ) {
        "tables"
      } else {
        "figures"
      }
      
      collection <- project[[collection_name]]
      
      artifact_position <- which(
        vapply(
          collection,
          function(record) {
            identical(
              record$id,
              input$manage_artifact_id
            )
          },
          logical(1)
        )
      )
      
      if (length(artifact_position) == 0) {
        deletion_message(
          list(
            ok = FALSE,
            text = "Artefato não encontrado."
          )
        )
        deletion_index_result(NULL)
        return()
      }
      
      artifact_position <- artifact_position[[1]]
      record <- collection[[artifact_position]]
      artifact_type <- input$manage_artifact_type
      
      known_versions <- as.integer(
        unlist(
          record$versions,
          use.names = FALSE
        )
      )
      
      if (length(known_versions) == 0) {
        known_versions <- seq_len(
          as.integer(record$latest_version)
        )
      }
      
      if (identical(input$manage_delete_scope, "artifact")) {
        paths_to_delete <- vapply(
          known_versions,
          function(version) {
            github_artifact_file_path(
              project_id = project$project_id,
              artifact_type = artifact_type,
              artifact_id = record$id,
              version = version
            )
          },
          character(1)
        )
        
        collection <- collection[-artifact_position]
        
        result_description <- paste(
          "Artefato excluído:",
          record$id
        )
      } else {
        remove_version <- as.integer(input$manage_version)
        
        if (!remove_version %in% known_versions) {
          deletion_message(
            list(
              ok = FALSE,
              text = "A versão selecionada não existe no índice."
            )
          )
          deletion_index_result(NULL)
          return()
        }
        
        paths_to_delete <- github_artifact_file_path(
          project_id = project$project_id,
          artifact_type = artifact_type,
          artifact_id = record$id,
          version = remove_version
        )
        
        remaining_versions <- setdiff(
          known_versions,
          remove_version
        )
        
        if (length(remaining_versions) == 0) {
          collection <- collection[-artifact_position]
          
          result_description <- paste(
            "A única versão foi excluída;",
            record$id,
            "também saiu do índice."
          )
        } else {
          record$versions <- as.list(
            sort(remaining_versions)
          )
          
          record$latest_version <- max(
            remaining_versions
          )
          
          collection[[artifact_position]] <- record
          
          result_description <- paste(
            "Versão excluída:",
            paste0(
              record$id,
              " v",
              remove_version
            )
          )
        }
      }
      
      project[[collection_name]] <- collection
      projects[[project_position]] <- project
    }
    
    index$projects <- projects
    
    manage_delete_in_progress(TRUE)
    
    deletion_message(
      list(
        ok = TRUE,
        text = "Atualizando o índice no GitHub..."
      )
    )
    
    tryCatch(
      {
        # Primeiro remove as referências públicas.
        github_put_json_file(
          path = "data/index.json",
          object = index,
          commit_message = paste(
            "Excluir conteúdo:",
            expected
          )
        )
        
        # Depois remove os arquivos físicos.
        deletion_failures <- character(0)
        
        for (path in unique(paths_to_delete)) {
          tryCatch(
            {
              github_delete_file(
                path = path,
                commit_message = paste(
                  "Excluir",
                  basename(path)
                )
              )
            },
            error = function(error) {
              deletion_failures <<- c(
                deletion_failures,
                paste0(
                  path,
                  ": ",
                  conditionMessage(error)
                )
              )
            }
          )
        }
        
        active_project_index(
          convert_github_index_to_project_index(index)
        )
        
        github_full_index(index)
        
        deletion_index_result(index)
        
        updateTextInput(
          session,
          "manage_confirmation",
          value = ""
        )
        
        if (length(deletion_failures) == 0) {
          deletion_message(
            list(
              ok = TRUE,
              text = paste(
                result_description,
                "O index.json e os arquivos foram atualizados."
              )
            )
          )
          
          showNotification(
            result_description,
            type = "message",
            duration = 6
          )
        } else {
          deletion_message(
            list(
              ok = FALSE,
              text = paste(
                result_description,
                "O índice foi atualizado, mas alguns arquivos",
                "não puderam ser apagados:",
                paste(
                  deletion_failures,
                  collapse = " | "
                )
              )
            )
          )
          
          showNotification(
            paste(
              "O índice foi atualizado, mas houve falhas",
              "ao apagar alguns arquivos."
            ),
            type = "warning",
            duration = 10
          )
        }
      },
      error = function(error) {
        deletion_index_result(NULL)
        
        deletion_message(
          list(
            ok = FALSE,
            text = paste(
              "A exclusão não foi concluída:",
              conditionMessage(error)
            )
          )
        )
        
        showNotification(
          paste(
            "Falha na exclusão:",
            conditionMessage(error)
          ),
          type = "error",
          duration = 10
        )
      },
      finally = {
        manage_delete_in_progress(FALSE)
      }
    )
  })
  
  
  
