  updated_upload_index <- reactive({
    artifact <- final_upload_artifact()
    projects <- current_index_projects()
    
    project_positions <- which(
      vapply(
        projects,
        function(project) {
          identical(
            project$project_id,
            artifact$project$id
          )
        },
        logical(1)
      )
    )
    
    if (length(project_positions) == 0) {
      projects[[length(projects) + 1]] <- list(
        year = artifact$project$year,
        analyst = artifact$project$analyst,
        project_id = artifact$project$id,
        project_name = artifact$project$name,
        tables = list(),
        figures = list()
      )
      
      project_position <- length(projects)
    } else {
      project_position <- project_positions[[1]]
    }
    
    project <- projects[[project_position]]
    
    collection_name <- if (
      identical(
        artifact$artifact$type,
        "table"
      )
    ) {
      "tables"
    } else {
      "figures"
    }
    
    collection <- project[[collection_name]]
    
    artifact_positions <- which(
      vapply(
        collection,
        function(record) {
          identical(
            record$id,
            artifact$artifact$id
          )
        },
        logical(1)
      )
    )
    
    new_record <- list(
      id = artifact$artifact$id,
      title = artifact$artifact$title,
      latest_version = artifact$artifact$version,
      versions = as.list(
        seq_len(artifact$artifact$version)
      )
    )
    
    if (
      identical(
        artifact$artifact$type,
        "figure"
      )
    ) {
      chart_type <- artifact$content$type
      
      if (is.null(chart_type)) {
        chart_type <- artifact$content$chart_type
      }
      
      if (!is.null(chart_type)) {
        new_record$type <- chart_type
      }
    }
    
    if (length(artifact_positions) == 0) {
      collection[[length(collection) + 1]] <- new_record
    } else {
      artifact_position <- artifact_positions[[1]]
      previous_record <- collection[[artifact_position]]
      
      previous_versions <- unlist(
        previous_record$versions,
        use.names = FALSE
      )
      
      all_versions <- sort(
        unique(
          as.integer(
            c(
              previous_versions,
              artifact$artifact$version
            )
          )
        )
      )
      
      new_record$versions <- as.list(all_versions)
      new_record$latest_version <- max(all_versions)
      
      collection[[artifact_position]] <- new_record
    }
    
    project[[collection_name]] <- collection
    projects[[project_position]] <- project
    
    projects <- projects[
      order(
        vapply(
          projects,
          function(record) {
            paste0(
              record$year,
              "|",
              record$analyst,
              "|",
              record$project_id
            )
          },
          character(1)
        )
      )
    ]
    
    list(
      index_format_version = "1.0",
      projects = projects
    )
  })
  
  
