  observeEvent(
    input$save_artifact_to_github,
    {
      req(!isTRUE(github_save_in_progress()))
      
      if (!github_admin_access_enabled()) {
        github_save_status(
          list(
            ok = FALSE,
            message = paste(
              "Modo somente leitura.",
              "O salvamento só está disponível na instalação administrativa local."
            )
          )
        )
        return()
      }
      
      artifact <- final_upload_artifact()
      index <- updated_upload_index()
      artifact_path <- github_artifact_path()
      
      existing <- github_get_file_metadata(artifact_path)
      
      if (!is.null(existing)) {
        github_save_status(
          list(
            ok = FALSE,
            message = paste(
              "Esta versão já existe:",
              artifact_path
            )
          )
        )
        return()
      }
      
      github_save_in_progress(TRUE)
      github_save_status(
        list(ok = TRUE, message = "Enviando artefato...")
      )
      
      artifact_created <- FALSE
      
      tryCatch(
        {
          github_put_json_file(
            path = artifact_path,
            object = artifact,
            commit_message = paste(
              "Adicionar",
              artifact$artifact$id,
              paste0("v", sprintf("%03d", artifact$artifact$version))
            )
          )
          
          artifact_created <- TRUE
          
          github_save_status(
            list(
              ok = TRUE,
              message = "Artefato enviado; atualizando index.json..."
            )
          )
          
          github_put_json_file(
            path = "data/index.json",
            object = index,
            commit_message = paste(
              "Atualizar índice após",
              artifact$artifact$id,
              paste0("v", sprintf("%03d", artifact$artifact$version))
            )
          )
          
          active_project_index(
            convert_github_index_to_project_index(index)
          )
          
          github_full_index(index)
          
          github_index_status_value(
            list(
              state = "success",
              message = paste0(
                "GitHub conectado · ",
                length(index$projects),
                if (length(index$projects) == 1) {
                  " projeto"
                } else {
                  " projetos"
                }
              )
            )
          )
          
          github_save_status(
            list(
              ok = TRUE,
              message = paste(
                "Salvo com sucesso:",
                artifact_path
              )
            )
          )
          
          showNotification(
            paste(
              artifact$artifact$id,
              paste0("v", sprintf("%03d", artifact$artifact$version)),
              "foi salvo no GitHub."
            ),
            type = "message",
            duration = 6
          )
        },
        error = function(error) {
          rollback_message <- ""
          
          if (isTRUE(artifact_created)) {
            rollback_message <- tryCatch(
              {
                github_delete_file(
                  artifact_path,
                  paste(
                    "Reverter upload incompleto de",
                    artifact$artifact$id
                  )
                )
                " O artefato foi removido automaticamente."
              },
              error = function(rollback_error) {
                paste(
                  " Falha também na reversão:",
                  conditionMessage(rollback_error)
                )
              }
            )
          }
          
          github_save_status(
            list(
              ok = FALSE,
              message = paste0(
                conditionMessage(error),
                rollback_message
              )
            )
          )
          
          showNotification(
            paste0(
              "Falha ao salvar: ",
              conditionMessage(error),
              rollback_message
            ),
            type = "error",
            duration = 12
          )
        },
        finally = {
          github_save_in_progress(FALSE)
        }
      )
    }
  )
  
  
  output$upload_ready_for_download <- reactive({
    result <- upload_validation_message()
    content <- normalized_upload_content()
    
    !is.null(result) &&
      length(result$problems) == 0 &&
      !is.null(content)
  })
  
  outputOptions(
    output,
    "upload_ready_for_download",
    suspendWhenHidden = FALSE
  )
  
  
  output$final_artifact_preview <- renderPrint({
    cat(
      jsonlite::toJSON(
        final_upload_artifact(),
        pretty = TRUE,
        auto_unbox = TRUE,
        null = "null",
        na = "null"
      )
    )
  })
  
  
  
  
  
  
  
  # ==========================================================
  # DOWNLOADS JSON DIRETAMENTE NO NAVEGADOR
  # Compatíveis com Shiny tradicional e Shinylive.
  # ==========================================================
  
  send_json_browser_download <- function(
    object,
    filename
  ) {
    json_text <- as.character(
      jsonlite::toJSON(
        object,
        pretty = TRUE,
        auto_unbox = TRUE,
        null = "null",
        na = "null"
      )
    )
    
    session$sendCustomMessage(
      "download-json-browser",
      list(
        filename = filename,
        content = json_text
      )
    )
  }
  
  
  observeEvent(
    input$download_final_artifact_browser,
    {
      send_json_browser_download(
        final_upload_artifact(),
        final_artifact_filename()
      )
    }
  )
  
  
  observeEvent(
    input$download_updated_index_browser,
    {
      send_json_browser_download(
        updated_upload_index(),
        "index.json"
      )
    }
  )
  
  
  observeEvent(
    input$download_index_after_deletion_browser,
    {
      req(deletion_index_result())
      
      send_json_browser_download(
        deletion_index_result(),
        "index.json"
      )
    }
  )
  
  
  observeEvent(
    input$json_browser_download_status,
    {
      status <- input$json_browser_download_status
      
      if (is.null(status)) {
        return()
      }
      
      if (!isTRUE(status$ok)) {
        showNotification(
          status$message,
          type = "error",
          duration = 6
        )
      } else {
        showNotification(
          paste(
            status$filename,
            "foi gerado."
          ),
          type = "message",
          duration = 4
        )
      }
    }
  )
  
  
}


shinyApp(
  ui = ui,
  server = server
)
